const RAW = [
{p:"01_Metabolismo_Terminale.pdf",m:1,q:[
{d:"Cosa si intende per 'via metabolica'?",o:["Un insieme di reazioni indipendenti che condividono il medesimo cofattore enzimatico","Un sistema sequenziale di reazioni in cui il prodotto di un enzima diventa substrato del successivo","Una rete di reazioni all'equilibrio termodinamico governata da un unico enzima allosterico","Un complesso multienzimatico che catalizza più reazioni parallele e indipendenti"],r:1,s:"Una via metabolica è un sistema sequenziale di reazioni in cui il prodotto del 1° enzima diventa substrato del 2° e così via, trasformando un substrato in un prodotto finale attraverso vari intermedi metabolici (metaboliti)."},
{d:"Quale tra queste è una via metabolica di tipo CICLICO?",o:["La glicolisi anaerobia secondo la via di Embden-Meyerhof","Il ciclo di Krebs (ciclo dell'acido citrico)","La via dei pentoso fosfati o shunt dell'esoso monofosfato","La β-ossidazione mitocondriale degli acidi grassi a catena lunga"],r:1,s:"Il ciclo di Krebs è l'esempio classico di via metabolica ciclica: l'ossalacetato viene rigenerato alla fine del ciclo. La sequenza Tirosina → L-DOPA → Dopamina → Noradrenalina → Adrenalina è invece una via lineare."},
{d:"Perché la compartimentazione delle vie metaboliche rappresenta un importante punto di controllo?",o:["Perché costringe gli enzimi anabolici e catabolici antagonisti a condividere lo stesso pool di intermedi","Perché la disponibilità dei substrati dipende dall'efficienza dei sistemi di trasporto attraverso le membrane","Perché rende superflua la regolazione allosterica degli enzimi che limitano la velocità della via","Perché determina la sintesi degli enzimi a livello trascrizionale in risposta agli stimoli ormonali"],r:1,s:"La diversa localizzazione delle vie metaboliche è un punto di controllo perché la disponibilità dei substrati dipende dall'efficienza dei sistemi di trasporto attraverso le membrane."},
{d:"Il controllo dell'attività enzimatica può avvenire tramite:",o:["Variazione del numero di molecole enzimatiche tramite sintesi e degradazione proteica","Interazione reversibile con ligandi (substrati, prodotti, modulatori allosterici) e modificazione covalente","Compartimentazione subcellulare e variazione dell'efficienza dei trasportatori di membrana","Spostamento dell'equilibrio termodinamico delle reazioni catalizzate dall'enzima"],r:1,s:"Il controllo dell'attività enzimatica avviene sia tramite interazione reversibile con ligandi (substrati, prodotti o modulatori allosterici) sia tramite modificazione covalente dell'enzima. Il controllo dei livelli enzimatici avviene invece tramite regolazione genica."},
{d:"Quale tra le seguenti caratterizza il CATABOLISMO?",o:["È un processo riduttivo che consuma ATP per costruire molecole complesse","È un processo ossidativo che degrada nutrienti producendo ATP e coenzimi ridotti","È un processo biosintetico che utilizza il potere riducente fornito dal NADPH","È un processo di interconversione che mantiene costante il numero di intermedi"],r:1,s:"Il catabolismo è un processo ossidativo: degrada sostanze ricche di energia (carboidrati, grassi, proteine) in prodotti poveri di energia (CO2, H2O, NH3), conservando circa il 40% dell'energia liberata in ATP e coenzimi ridotti (NADH, NADPH, FADH2)."},
{d:"Quali sono i prodotti finali poveri di energia del catabolismo?",o:["Glucosio, acidi grassi a catena lunga e corpi chetonici","Anidride carbonica (CO2), acqua (H2O) e ammoniaca (NH3)","ATP, GTP e coenzimi ridotti come NADH e FADH2","Piruvato, acetil-CoA e intermedi del ciclo di Krebs"],r:1,s:"I prodotti finali poveri di energia del catabolismo sono anidride carbonica (CO2), acqua (H2O) e ammoniaca (NH3). ATP e coenzimi ridotti sono invece la forma in cui viene conservata l'energia."},
{d:"Circa quale percentuale dell'energia liberata dalle reazioni cataboliche viene conservata nell'ATP e nei coenzimi ridotti?",o:["Circa il 25%","Circa il 40%","Circa il 55%","Circa il 70%"],r:1,s:"Solo circa il 40% dell'energia che si libera dalle reazioni cataboliche viene conservata nell'ATP e nei coenzimi ridotti; il resto si disperde principalmente come calore."},
{d:"Quale molecola rappresenta il punto di convergenza di tutte le vie cataboliche con cui vengono degradate le macromolecole biologiche?",o:["Il piruvato","L'acetil-CoA","L'ossalacetato","Il malato"],r:1,s:"L'acetil-CoA rappresenta il punto di convergenza di tutte le vie cataboliche: glucidi, lipidi e amminoacidi vengono tutti degradati ad acetil-CoA, che entra poi nel ciclo di Krebs."},
{d:"Nella prima fase del catabolismo (degradazione), cosa accade?",o:["I coenzimi ridotti cedono i loro elettroni alla catena respiratoria per produrre ATP","Le macromolecole vengono degradate con diminuzione della complessità e formazione di acetil-CoA","Gli intermedi a basso peso molecolare vengono ossidati completamente ad anidride carbonica","I precursori semplici vengono assemblati in polimeri con consumo di ATP e potere riducente"],r:1,s:"La prima fase (degradazione) comporta ossidazione, produzione di ATP (es. glicolisi), diminuzione del grado di complessità delle molecole e formazione di un intermedio comune: l'acetil-CoA."},
{d:"La terza fase del catabolismo è caratterizzata da:",o:["Degradazione delle macromolecole nei rispettivi monomeri costitutivi","Utilizzo del potere riducente per produrre ATP (fosforilazione ossidativa)","Convergenza degli intermedi metabolici nella formazione di acetil-CoA","Ossidazione dell'acetil-CoA a CO2 all'interno del ciclo dell'acido citrico"],r:1,s:"Nella terza fase si utilizza il potere riducente (NADH e FADH2) derivante dall'ossidazione dell'acetil-CoA per produrre ATP, attraverso la catena respiratoria e la fosforilazione ossidativa."},
{d:"Cosa si intende per METABOLISMO TERMINALE?",o:["L'insieme delle reazioni citosoliche che convertono il glucosio in piruvato producendo una resa netta di ATP in assenza di ossigeno","L'insieme delle reazioni a carattere ossidativo che si svolgono nei mitocondri ed è il principale meccanismo per la produzione di energia","L'insieme delle vie biosintetiche citosoliche che consumano potere riducente sotto forma di NADPH per produrre macromolecole complesse","L'insieme delle reazioni di degradazione che scindono le macromolecole nei loro precursori semplici riducendone il grado di complessità"],r:1,s:"Il metabolismo terminale è l'insieme delle reazioni a carattere ossidativo che si svolgono nei mitocondri e che costituiscono il principale meccanismo per la produzione di energia (ciclo di Krebs + fosforilazione ossidativa)."},
{d:"Dove si svolge il ciclo di Krebs?",o:["Nel citosol, in stretta associazione con gli enzimi della glicolisi","Nella matrice mitocondriale (con un'eccezione sulla membrana interna)","Sulla membrana mitocondriale esterna, con i siti attivi rivolti al citosol","Nello spazio intermembrana, tra le due membrane mitocondriali"],r:1,s:"Il ciclo di Krebs è una via metabolica ciclica mitocondriale. Sette enzimi sono nella matrice mitocondriale; solo la succinato deidrogenasi è associata alla membrana mitocondriale interna (MMI)."},
{d:"Qual è il bilancio dei coenzimi/nucleotidi prodotti dal ciclo di Krebs per ogni acetil-CoA ossidato?",o:["2 NADH(H+), 1 FADH2 e 1 GTP","3 NADH(H+), 1 FADH2 e 1 GTP","3 NADH(H+), 2 FADH2 e 1 ATP","4 NADH(H+), 1 FADH2 e 1 GTP"],r:1,s:"Nel ruolo catabolico, per ogni acetil-CoA il ciclo produce 3 NADH(H+), 1 FADH2 e 1 GTP, oltre a 2 molecole di CO2 dalla completa ossidazione dell'acetile."},
{d:"Cosa caratterizza il ruolo ANABOLICO del ciclo di Krebs?",o:["L'ossidazione completa dei gruppi acetilici a due molecole di anidride carbonica","La produzione di intermedi usati come precursori in numerose vie biosintetiche","La generazione di coenzimi ridotti destinati alla fosforilazione ossidativa","La fosforilazione a livello del substrato con formazione diretta di GTP"],r:1,s:"Il ruolo anabolico del ciclo consiste nella produzione di intermedi (citrato, α-chetoglutarato, succinil-CoA, ossalacetato) usati come precursori per la sintesi di acidi grassi, amminoacidi, nucleotidi, gruppo eme e per la gluconeogenesi."},
{d:"Da quante reazioni ed enzimi è costituito il ciclo di Krebs?",o:["10 reazioni catalizzate da 10 enzimi","8 reazioni catalizzate da 8 enzimi","9 reazioni catalizzate da 8 enzimi","8 reazioni catalizzate da 6 enzimi"],r:1,s:"Il ciclo di Krebs avviene con 8 reazioni catalizzate da 8 enzimi localizzati a livello mitocondriale."},
{d:"Quale enzima del ciclo di Krebs è l'unico associato alla membrana mitocondriale interna (e non alla matrice)?",o:["La citrato sintasi","La succinato deidrogenasi","L'isocitrato deidrogenasi","La malato deidrogenasi"],r:1,s:"La succinato deidrogenasi è l'unico enzima del ciclo associato alla membrana mitocondriale interna (corrisponde anche al Complesso II della catena respiratoria), mentre gli altri 7 enzimi sono nella matrice."},
{d:"Quale reazione catalizza la citrato sintasi?",o:["L'isomerizzazione del citrato a isocitrato passando per il cis-aconitato","La condensazione di acetil-CoA e ossalacetato per formare citrato","La decarbossilazione ossidativa dell'isocitrato ad α-chetoglutarato","L'idratazione stereospecifica del fumarato a L-malato"],r:1,s:"La citrato sintasi catalizza la prima reazione del ciclo: la condensazione (aldolica/di Claisen) tra acetil-CoA e ossalacetato, con formazione dell'intermedio citril-CoA e poi del citrato."},
{d:"Perché la reazione della citrato sintasi è IRREVERSIBILE?",o:["Perché la condensazione consuma una molecola di ATP, la cui idrolisi sposta fortemente l'equilibrio verso i prodotti","Perché l'idrolisi del citril-CoA è fortemente spostata a destra (ΔG'° = -32,2 kJ/mol) e fornisce la spinta termodinamica","Perché libera una molecola di CO2 che, abbandonando il sistema in fase gassosa, rende il processo irreversibile","Perché l'ossalacetato si lega in modo covalente e permanente al sito attivo impedendo la reazione inversa"],r:1,s:"La formazione di citril-CoA induce un cambiamento conformazionale che intrappola una molecola d'acqua. L'idrolisi del tioestere è fortemente spostata a destra (ΔG'° = -32,2 kJ/mol) e fornisce la spinta termodinamica, rendendo la reazione irreversibile."},
{d:"Quali molecole sono inibitori allosterici della citrato sintasi?",o:["ADP e AMP","NADH e succinil-CoA","NAD+ e coenzima A libero","Piruvato e acetil-CoA"],r:1,s:"La citrato sintasi è sede di regolazione allosterica: NADH e succinil-CoA (oltre a citrato e ATP) sono suoi inibitori, segnalando abbondanza energetica."},
{d:"Quale tipo di reazione catalizza l'aconitasi?",o:["Una decarbossilazione ossidativa accoppiata alla riduzione del NAD+ a NADH","Un'isomerizzazione reversibile (citrato → isocitrato) tramite deidratazione/reidratazione","Una condensazione tra un gruppo acetilico e un composto dicarbossilico","Una fosforilazione a livello del substrato con formazione di GTP"],r:1,s:"L'aconitasi catalizza un'isomerizzazione reversibile del citrato in isocitrato, passando per l'intermedio cis-aconitato (che non si dissocia dall'enzima), tramite una deidratazione seguita da una reidratazione."},
{d:"Quale cofattore contiene l'aconitasi nel suo sito attivo?",o:["Un gruppo eme con il ferro coordinato da un'istidina prossimale","Un centro Fe-S coordinato da tre residui di cisteina","Uno ione zinco coordinato da residui di istidina e cisteina","Una molecola di FAD legata covalentemente all'apoenzima"],r:1,s:"L'aconitasi contiene un centro Fe-S coordinato da tre residui di cisteina, che serve a orientare correttamente il citrato e a stabilizzare le cariche negative favorendo la catalisi."},
{d:"L'aconitasi citosolica è definita un enzima 'MOONLIGHTING'. Cosa significa?",o:["Che alterna la propria attività catalitica seguendo il ritmo circadiano cellulare","Che svolge una seconda funzione, regolando l'omeostasi cellulare del ferro oltre al ruolo catalitico","Che richiede l'esposizione alla luce per assemblare il proprio centro ferro-zolfo","Che catalizza con pari efficienza sia la reazione diretta sia quella inversa"],r:1,s:"L'aconitasi citosolica è un enzima 'moonlighting' perché, oltre al ruolo catalitico, partecipa all'omeostasi cellulare del ferro: a basse [Fe] perde il centro Fe-S e l'apoenzima diventa una proteina regolatoria (IRP)."},
{d:"A basse concentrazioni di ferro, l'apoaconitasi (priva del centro Fe-S) come agisce sull'mRNA della ferritina?",o:["Si lega al 3' dell'mRNA della ferritina stabilizzandolo e aumentando lo storage del Fe","Si lega al 5' dell'mRNA della ferritina inibendone la traduzione (riducendo lo storage del Fe)","Promuove la poliadenilazione dell'mRNA della ferritina aumentandone la traduzione","Catalizza il taglio endonucleolitico dell'mRNA della ferritina avviandone la degradazione"],r:1,s:"A basse [Fe] l'apoaconitasi si lega al 5' dell'mRNA che codifica per la ferritina, inibendone la traduzione e riducendo così lo storage del ferro (inutile depositarlo quando scarseggia)."},
{d:"A basse [Fe], come agisce l'apoaconitasi sull'mRNA del recettore della transferrina?",o:["Si lega al 5' dell'mRNA bloccandone la traduzione e riducendo l'uptake del Fe","Si lega al 3' dell'mRNA aumentandone la stabilità e promuovendo l'uptake del Fe","Ne stimola la degradazione riducendo il numero di recettori di superficie","Ne promuove la traduzione legandosi alla regione codificante centrale"],r:1,s:"A basse [Fe] l'apoaconitasi si lega al 3' dell'mRNA del recettore della transferrina aumentandone la stabilità: si produce più recettore, promuovendo l'uptake del ferro trasportato dalla transferrina."},
{d:"Quale proteina rappresenta il principale deposito (storage) del ferro nei tessuti?",o:["La transferrina","La ferritina","La ceruloplasmina","Il recettore della transferrina"],r:1,s:"La ferritina è la proteina di deposito del ferro nei tessuti. La transferrina è invece la proteina di trasporto del ferro in circolo, e il recettore della transferrina ne permette l'internalizzazione."},
{d:"Quale reazione catalizza l'isocitrato deidrogenasi?",o:["Un'isomerizzazione reversibile dell'isocitrato a citrato passando per il cis-aconitato","Una decarbossilazione ossidativa dell'isocitrato ad α-chetoglutarato con produzione di NADH e CO2","Una fosforilazione a livello del substrato accoppiata alla sintesi di una molecola di GTP","Un'ossidazione FAD-dipendente dell'isocitrato con produzione di FADH2"],r:1,s:"L'isocitrato deidrogenasi catalizza una decarbossilazione ossidativa (ΔG'° = -22,2 kJ/mol) che trasforma l'isocitrato in α-chetoglutarato, producendo NADH e liberando una molecola di CO2 (passando per l'intermedio ossalosuccinato)."},
{d:"La reazione dell'isocitrato deidrogenasi rappresenta:",o:["Il passaggio finale di rigenerazione dell'ossalacetato del ciclo","Il primo punto di controllo del ciclo di Krebs","Una reazione anaplerotica che rifornisce il ciclo di intermedi","Il punto di fosforilazione a livello del substrato del ciclo"],r:1,s:"La decarbossilazione ossidativa catalizzata dall'isocitrato deidrogenasi (ΔG'° = -22,2 kJ/mol) rappresenta il primo punto di controllo del ciclo di Krebs."},
{d:"Quale cofattore usano le isoforme IDH1 (citosolica) e IDH2 (mitocondriale) dell'isocitrato deidrogenasi?",o:["NAD+, producendo NADH destinato alla catena respiratoria","NADP+, producendo NADPH usato come potere riducente","FAD, producendo FADH2 ceduto poi al coenzima Q","GDP, producendo GTP per fosforilazione a livello del substrato"],r:1,s:"Le isoforme IDH1 (citosolica) e IDH2 (mitocondriale) utilizzano NADP+ e producono NADPH usato come potere riducente. La forma mitocondriale del ciclo (IDH3) usa invece NAD+."},
{d:"Cosa accade quando i geni IDH1 e IDH2 sono mutati nei tumori umani?",o:["Si blocca la decarbossilazione con accumulo di citrato e arresto della crescita tumorale","Si accumula D-2HG (D-2-idrossiglutarato) che contribuisce alla formazione e progressione maligna dei tumori","Aumenta la produzione di NADPH che protegge le cellule dallo stress ossidativo","Si riduce la sintesi di α-chetoglutarato compromettendo la proliferazione cellulare"],r:1,s:"I geni IDH1 e IDH2 sono mutati in vari tumori umani. L'eccesso di D-2HG (oncometabolita) che si accumula nel citoplasma contribuisce alla formazione e alla progressione maligna dei tumori, alterando la metilazione di istoni e DNA e il differenziamento cellulare."},
{d:"Come è regolata la isocitrato deidrogenasi mitocondriale?",o:["Dallo stato energetico cellulare: attivata da ATP/NADH, inibita da ADP e ioni Ca2+","Dallo stato energetico cellulare: attivata da ADP/Ca2+, inibita da ATP e NADH(H+)","Dalla fosforilazione reversibile a opera di una chinasi e di una fosfatasi specifiche","Dalla concentrazione di ossigeno e dal potenziale di membrana mitocondriale"],r:1,s:"La isocitrato deidrogenasi mitocondriale è regolata dallo stato energetico cellulare: ATP e NADH(H+) la inattivano (abbondanza di energia), mentre ADP, NAD+ e Ca2+ la attivano. Quando è inibita si accumula citrato destinato alla biosintesi dei lipidi."},
{d:"Quale reazione catalizza il complesso dell'α-chetoglutarato deidrogenasi?",o:["L'ossidazione FAD-dipendente del succinato a fumarato, con produzione di FADH2","La decarbossilazione ossidativa dell'α-chetoglutarato a succinil-CoA, con produzione di NADH e CO2","La fosforilazione a livello del substrato del succinil-CoA a succinato e GTP","L'idratazione stereospecifica del fumarato a L-malato senza intervento di coenzimi"],r:1,s:"Il complesso dell'α-chetoglutarato deidrogenasi catalizza una decarbossilazione ossidativa (ΔG'° = -33,5 kJ/mol) trasformando l'α-chetoglutarato in succinil-CoA, con produzione di NADH e liberazione della seconda molecola di CO2."},
{d:"A quale altro complesso enzimatico è del tutto analogo il complesso dell'α-chetoglutarato deidrogenasi?",o:["Al complesso della succinato deidrogenasi (Complesso II)","Al complesso della piruvato deidrogenasi","Al complesso della succinil-CoA sintetasi","Al complesso della NADH deidrogenasi (Complesso I)"],r:1,s:"Il complesso dell'α-chetoglutarato deidrogenasi è un complesso di tre enzimi del tutto analogo al complesso della piruvato deidrogenasi (usa TPP, lipoamide, FAD, NAD+ e CoA-SH)."},
{d:"Quali sono gli effettori allosterici negativi del complesso dell'α-chetoglutarato deidrogenasi?",o:["ADP e ione calcio","Succinil-CoA e NADH","NAD+ e coenzima A libero","α-chetoglutarato e ATP"],r:1,s:"Il complesso dell'α-chetoglutarato deidrogenasi è regolato da effettori allosterici negativi quali succinil-CoA e NADH (i suoi prodotti), che ne segnalano l'eccesso. È attivato dal Ca2+."},
{d:"In quale forma viene conservata l'energia derivante dalla reazione dell'α-chetoglutarato deidrogenasi?",o:["Nel legame fosfoanidridico ad alta energia di una molecola di GTP","Nel legame tioestere ad alta energia del succinil-CoA","Nel gradiente protonico generato attraverso la membrana mitocondriale interna","Nel legame estere tra il coenzima A e il gruppo succinilico"],r:1,s:"L'energia derivante dall'ossidazione viene conservata nella formazione di un legame tioestere ad alta energia nel succinil-CoA, che verrà poi utilizzato per la sintesi di GTP nella reazione successiva."},
{d:"Quante molecole di CO2 vengono liberate complessivamente nel ciclo di Krebs per ogni acetil-CoA, e in quali reazioni?",o:["1 CO2, liberata dalla decarbossilazione dell'isocitrato","2 CO2, dalla isocitrato deidrogenasi e dall'α-chetoglutarato deidrogenasi","3 CO2, da isocitrato deidrogenasi, α-chetoglutarato deidrogenasi e succinato deidrogenasi","2 CO2, liberate dalla citrato sintasi e dalla malato deidrogenasi"],r:1,s:"Vengono liberate 2 molecole di CO2 per acetil-CoA: la prima dalla isocitrato deidrogenasi e la seconda dall'α-chetoglutarato deidrogenasi. Queste due decarbossilazioni rappresentano la completa ossidazione dell'acetile immesso nel ciclo."},
{d:"Quale tipo di reazione catalizza la succinil-CoA sintetasi?",o:["Una decarbossilazione ossidativa con riduzione del NAD+ a NADH","Una fosforilazione a livello del substrato, con formazione di GTP (o ATP)","Un'idratazione del doppio legame con formazione di un gruppo ossidrilico","Un'isomerizzazione reversibile catalizzata da un centro ferro-zolfo"],r:1,s:"La succinil-CoA sintetasi catalizza una fosforilazione a livello del substrato: l'energia del legame tioestere del succinil-CoA è accoppiata alla fosforilazione di un nucleoside difosfato purinico (GDP→GTP o ADP→ATP). ΔG'° = -2,9 kJ/mol."},
{d:"Riguardo alla struttura della succinil-CoA sintetasi:",o:["È un omotetramero in cui ciascuna subunità reca un gruppo biotina legato covalentemente a una lisina del sito attivo catalitico","È formata da due subunità (α e β): la α possiede l'istidina fosforilabile, la β conferisce specificità per ADP o GDP; il sito attivo è all'interfaccia","È un monomero globulare con un unico sito attivo che lega in sequenza il substrato, il coenzima A e il nucleotide difosfato purinico","È un complesso costituito da tre enzimi distinti che impiega tiamina pirofosfato, lipoammide e FAD come gruppi prostetici di reazione"],r:1,s:"La succinil-CoA sintetasi è formata da due subunità: la subunità α possiede il residuo di istidina fosforilabile, mentre la subunità β conferisce specificità per ADP o GDP. Il sito attivo è all'interfaccia tra le due subunità."},
{d:"Nelle cellule animali esistono due forme isoenzimatiche della succinil-CoA sintetasi. Come si distinguono?",o:["Una è mitocondriale e specifica per il NAD+, l'altra citosolica e specifica per il NADP+","Una è specifica per il GDP (fegato) e l'altra per ADP (muscolo scheletrico e cardiaco)","Una opera nella direzione anabolica e l'altra in quella catabolica del ciclo","Una è attivata dalla fosforilazione e l'altra dalla defosforilazione covalente"],r:1,s:"Nelle cellule animali sono presenti due isoenzimi della succinil-CoA sintetasi: una forma specifica per il GDP (nel fegato) e una specifica per ADP (nel muscolo scheletrico e cardiaco)."},
{d:"Per quale di queste reazioni può essere utilizzato il GTP prodotto dalla succinil-CoA sintetasi?",o:["Per la fosforilazione iniziale del glucosio a glucosio-6-fosfato, per la glicolisi citosolica e per la sintesi del glicogeno epatico","Per la formazione del fosfoenolpiruvato (PEP) dall'ossalacetato nella gluconeogenesi, per la sintesi proteica e per la trasduzione del segnale","Per l'attivazione degli acidi grassi a derivati acil-CoA, per la loro β-ossidazione mitocondriale e per la sintesi dei corpi chetonici","Per la riduzione dei coenzimi nella catena respiratoria, per il trasporto mitocondriale degli elettroni e per la sintesi aerobia di ATP"],r:1,s:"Il GTP prodotto può essere usato per reazioni GTP-dipendenti: formazione del PEP dall'ossalacetato (gluconeogenesi, via PEPCK), reazione terminale della sintesi proteica e scissione a GDP da parte delle GTPasi (trasduzione del segnale)."},
{d:"Quale enzima converte il GTP in ATP mediante trasferimento di un radicale fosforico?",o:["La succinil-CoA sintetasi nella sua isoforma epatica","La GTP-ADP fosfotransferasi (nucleoside difosfato chinasi)","L'adenilato chinasi (mioadenilato chinasi citosolica)","La nucleoside monofosfato chinasi della matrice mitocondriale"],r:1,s:"Il GTP può essere convertito in ATP per trasferimento di un radicale fosforico (GTP + ADP ⇌ GDP + ATP, ΔG'° = 0 kJ/mol), reazione catalizzata dalla GTP-ADP fosfotransferasi (nucleoside difosfato chinasi)."},
{d:"Quale reazione del ciclo di Krebs è catalizzata da un enzima FAD-dipendente?",o:["La decarbossilazione ossidativa dell'isocitrato (isocitrato deidrogenasi)","L'ossidazione del succinato a fumarato (succinato deidrogenasi)","L'ossidazione del L-malato a ossalacetato (malato deidrogenasi)","La decarbossilazione ossidativa dell'α-chetoglutarato (α-chetoglutarato deidrogenasi)"],r:1,s:"La succinato deidrogenasi è un'ossidoreduttasi FAD-dipendente: ossida il succinato a fumarato producendo FADH2 (e non NADH). È l'unica deidrogenasi del ciclo che usa il FAD."},
{d:"Dove vengono trasferiti gli elettroni del FADH2 prodotto dalla succinato deidrogenasi?",o:["Direttamente al NAD+ della matrice per formare NADH e poi al complesso I","Tramite centri Fe-S al coenzima Q e quindi al complesso III della catena di trasporto","Tramite il citocromo c al complesso IV e infine all'ossigeno molecolare","Attraverso i centri Fe-S del complesso I e successivamente al coenzima Q"],r:1,s:"La succinato deidrogenasi (Complesso II) ha il sito attivo rivolto verso la matrice; gli elettroni del FADH2 vengono trasferiti mediante centri Fe-S al coenzima Q (ubichinone) e quindi al complesso III della catena di trasporto."},
{d:"A quale classe enzimatica appartiene la fumarasi e quale reazione catalizza?",o:["È un'idrolasi che scinde un legame del fumarato mediante l'aggiunta di una molecola d'acqua","È una LIASI che catalizza l'idratazione stereospecifica (addizione al doppio legame) del fumarato a L-malato","È un'ossidoreduttasi NAD-dipendente che ossida il fumarato producendo NADH","È un'isomerasi che converte la forma trans del fumarato nella corrispondente forma cis"],r:1,s:"La fumarasi è una LIASI: catalizza una reazione stereospecifica di idratazione del doppio legame trans del fumarato, formando L-malato. Attenzione: NON è un'idrolisi ma un'addizione di acqua al doppio legame."},
{d:"Quale reazione catalizza la malato deidrogenasi e cosa sposta il suo equilibrio?",o:["L'idratazione stereospecifica del fumarato a L-malato (ΔG'° ≈ -3,8 kJ/mol); l'equilibrio è spostato a destra dalla continua rimozione del malato a opera della malato deidrogenasi","L'ossidazione del L-malato a ossalacetato (NAD-dipendente); l'equilibrio (ΔG'° = +29,7 kJ/mol) è spostato a destra dalla continua rimozione dell'ossalacetato da parte della citrato sintasi","La decarbossilazione ossidativa del L-malato a piruvato (NADP-dipendente); l'equilibrio è spostato a destra dalla continua liberazione di CO2 che abbandona il sistema","La riduzione dell'ossalacetato a L-malato (NADH-dipendente); l'equilibrio è spostato a destra dal consumo costante di potere riducente fornito dalla glicolisi"],r:1,s:"La malato deidrogenasi è un'ossidoreduttasi NAD-dipendente che ossida il L-malato a ossalacetato. Pur avendo ΔG'° fortemente positivo (+29,7 kJ/mol), l'equilibrio è spostato a destra dalla continua rimozione dell'ossalacetato ad opera della citrato sintasi."},
{d:"Qual è la resa netta di ATP dall'ossidazione di un singolo acetil-CoA nel ciclo di Krebs (catena respiratoria inclusa)?",o:["12 ATP (9 dai 3 NADH + 2 dal FADH2 + 1 dal GTP)","10 ATP (7,5 dai 3 NADH + 1,5 dal FADH2 + 1 dal GTP)","5 ATP (3 dai 3 NADH + 1 dal FADH2 + 1 dal GTP)","11,5 ATP (7,5 dai 3 NADH + 2,5 dal FADH2 + 1,5 dal GTP)"],r:1,s:"L'ossidazione di un acetil-CoA rende 10 ATP: 3 NADH → 7,5 ATP, 1 FADH2 → 1,5 ATP, e 1 GTP (GDP+Pi) → 1 ATP."},
{d:"Quante molecole di ATP si formano dall'ossidazione completa di una molecola di piruvato a 3 CO2?",o:["10 ATP (prodotti interamente dall'ossidazione dell'acetil-CoA nel ciclo)","12,5 ATP (10 dall'acetil-CoA nel ciclo + 2,5 dalla reazione della PDH)","15 ATP (10 dal ciclo + 2,5 dalla PDH + 2,5 dalla fase glicolitica)","11 ATP (10 dall'acetil-CoA + 1 dal GTP della fosforilazione del substrato)"],r:1,s:"Partendo dal piruvato si formano 12,5 ATP: alle 10 ATP ricavate dall'acetil-CoA nel ciclo di Krebs si aggiungono le 2,5 ATP del NADH prodotto nella reazione della piruvato deidrogenasi (PDH)."},
{d:"Quanti ATP corrispondono ai 3 NADH(H+) prodotti dal ciclo di Krebs (per acetil-CoA)?",o:["3 ATP","7,5 ATP","9 ATP","6 ATP"],r:1,s:"I 3 NADH(H+) prodotti rendono 7,5 ATP nella catena respiratoria (ogni NADH ≈ 2,5 ATP). Il FADH2 rende 1,5 ATP e il GTP equivale a 1 ATP."},
{d:"Cosa sono le reazioni CATAPLEROTICHE del ciclo di Krebs?",o:["Reazioni che riforniscono il ciclo degli intermedi prelevati dalle vie biosintetiche","Reazioni che prelevano intermedi dal ciclo per la sintesi di altre biomolecole","Reazioni che ossidano completamente gli intermedi del ciclo liberando anidride carbonica","Reazioni che rigenerano i coenzimi ridotti consumati durante il ciclo"],r:1,s:"Le reazioni cataplerotiche prelevano intermedi dal ciclo per usarli come precursori biosintetici (es. citrato per gli acidi grassi, α-chetoglutarato per gli amminoacidi, succinil-CoA per l'eme), evitando anche un inutile accumulo di intermedi."},
{d:"Cosa sono le reazioni ANAPLEROTICHE?",o:["Reazioni che prelevano gli intermedi dal ciclo per le diverse vie biosintetiche cellulari","Reazioni che riforniscono il ciclo degli intermedi necessari quando rallenta per deficienza di substrati","Reazioni che accelerano il ciclo aumentando l'attività delle deidrogenasi regolatrici","Reazioni che rimuovono gli intermedi in eccesso convertendoli in anidride carbonica"],r:1,s:"Le reazioni anaplerotiche riforniscono il ciclo degli intermedi quando rallenta per carenza di substrati, mantenendo un bilancio quasi perfetto tra rimozione e rifornimento degli intermedi e una concentrazione costante."},
{d:"Quale intermedio del ciclo di Krebs viene prelevato per la sintesi del gruppo EME (porfirine)?",o:["L'α-chetoglutarato","Il succinil-CoA","Il citrato","L'ossalacetato"],r:1,s:"Il succinil-CoA è il precursore usato per la sintesi delle porfirine (gruppo eme). Il citrato è invece destinato alla sintesi degli acidi grassi, e l'α-chetoglutarato (via glutammato) alla sintesi di amminoacidi e nucleotidi."},
{d:"Quale intermedio del ciclo, tramite la sua trasformazione, alimenta la gluconeogenesi e (via aspartato) il ciclo dell'urea, la sintesi di nucleotidi e amminoacidi?",o:["Il succinil-CoA","L'ossalacetato","L'α-chetoglutarato","Il citrato"],r:1,s:"L'ossalacetato alimenta la gluconeogenesi (via PEP) e, tramite l'aspartato da esso derivato, contribuisce al ciclo dell'urea, alla sintesi di nucleotidi e di amminoacidi."},
{d:"Quale reazione catalizza la piruvato carbossilasi (reazione anaplerotica chiave)?",o:["Piruvato + CoA-SH + NAD+ → acetil-CoA + CO2 + NADH","Piruvato + CO2 + ATP → ossalacetato (+ ADP + Pi)","Piruvato + NADH + H+ → lattato + NAD+","Ossalacetato + GTP → fosfoenolpiruvato + CO2 + GDP"],r:1,s:"La piruvato carbossilasi catalizza la carbossilazione del piruvato a ossalacetato usando CO2 e ATP. È una reazione anaplerotica fondamentale per ripristinare l'ossalacetato del ciclo."},
{d:"Quale gruppo prostetico/cofattore è essenziale per la piruvato carbossilasi?",o:["La tiamina pirofosfato (TPP), legata a un residuo catalitico","La biotina, legata covalentemente a un residuo di lisina","Il piridossal fosfato, legato covalentemente a una lisina","L'acido lipoico, legato covalentemente a un residuo di lisina"],r:1,s:"La piruvato carbossilasi è un complesso di quattro subunità, ciascuna con un gruppo prostetico di biotina legato covalentemente a un residuo di lisina, che funge da trasportatore di CO2."},
{d:"Quale molecola è l'attivatore allosterico fondamentale della piruvato carbossilasi?",o:["Il NADH","L'acetil-CoA","L'ossalacetato","Il citrato"],r:1,s:"L'acetil-CoA è l'attivatore allosterico positivo della piruvato carbossilasi: quando l'acetil-CoA si accumula, segnala la necessità di più ossalacetato per farlo entrare nel ciclo (o per la gluconeogenesi)."},
{d:"Quali sono i tre enzimi del ciclo di Krebs che funzionano lontano dall'equilibrio (ΔG°<0) e ne controllano la velocità?",o:["Aconitasi, fumarasi e malato deidrogenasi","Citrato sintasi, isocitrato deidrogenasi e α-chetoglutarato deidrogenasi","Succinato deidrogenasi, fumarasi e succinil-CoA sintetasi","Citrato sintasi, succinato deidrogenasi e malato deidrogenasi"],r:1,s:"I tre enzimi che catalizzano reazioni irreversibili (ΔG°<0) e controllano la velocità del ciclo sono: citrato sintasi, isocitrato deidrogenasi e α-chetoglutarato deidrogenasi."},
{d:"Quali rapporti metabolici regolano principalmente il flusso del ciclo di Krebs?",o:["FADH2/FAD e GTP/GDP","NADH(H+)/NAD+ e ATP/ADP","Acetil-CoA/CoA libero e citrato/ossalacetato","NADPH/NADP+ e AMP/ATP"],r:1,s:"Il flusso del ciclo dipende dallo stato energetico, espresso dai rapporti NADH(H+)/NAD+ e ATP/ADP: valori elevati (energia abbondante) rallentano il ciclo, valori bassi (energia scarsa) lo accelerano."},
{d:"Come viene regolata la piruvato deidrogenasi (PDH) tramite modificazione covalente?",o:["Una fosfatasi la defosforila inattivandola; una chinasi la fosforila riattivandola","Una chinasi la fosforila inattivandola; una fosfatasi la defosforila riattivandola","Una chinasi la fosforila attivandola in risposta all'accumulo di acetil-CoA","Una proteasi rimuove un peptide inibitorio attivandola in modo irreversibile"],r:1,s:"La PDH è regolata per fosforilazione/defosforilazione: la PDH chinasi fosforila e inattiva l'enzima, mentre la PDH fosfatasi lo defosforila riattivandolo. La forma defosforilata è quella attiva."},
{d:"Da quali molecole viene inibita allostericamente la piruvato deidrogenasi (forma attiva defosforilata)?",o:["Dai suoi substrati piruvato e CoA-SH, e dall'ADP","Dai suoi prodotti acetil-CoA e NADH(H+), e da ATP","Dagli ioni calcio e magnesio in concentrazione elevata","Dal rapporto NAD+/NADH elevato e dall'AMP"],r:1,s:"La PDH viene inibita dai suoi stessi prodotti (acetil-CoA e NADH) e da ATP, tramite inibizione allosterica da prodotto sulla forma defosforilata attiva. Questi stessi segnali attivano anche la PDH chinasi."},
{d:"L'ossidazione dell'isoleucina (così come leucina e valina) genera un intermedio tramite decarbossilazione ossidativa. Quale prodotto si forma dall'α-chetoacido dell'isoleucina?",o:["Isovaleril-CoA","α-Metilbutirril-CoA","Isobutirril-CoA","Propionil-CoA"],r:1,s:"Le decarbossilazioni ossidative seguono uno schema comune (HS-CoA, NAD+→NADH, CO2). Dall'α-chetoacido dell'isoleucina si forma α-metilbutirril-CoA, analogamente a come il piruvato dà acetil-CoA e l'α-chetoglutarato dà succinil-CoA."},
{d:"Perché il ciclo di Krebs, dopo aver ossidato l'acetil-CoA a 2 CO2, prosegue fino al malato/ossalacetato?",o:["Per liberare le ultime due molecole di anidride carbonica derivate dal gruppo acetilico","Per ripristinare l'ossalacetato, necessario alla combustione di un'altra molecola di acetil-CoA","Per generare il potere riducente residuo destinato alla fosforilazione a livello del substrato","Per convertire il succinil-CoA nel precursore della sintesi del gruppo eme"],r:1,s:"Una volta che l'acetil-CoA è stato completamente ossidato a 2 CO2, il ciclo prosegue (succinato → fumarato → malato → ossalacetato) con lo scopo di rigenerare l'ossalacetato, indispensabile per condensarsi con un nuovo acetil-CoA e far ripartire il ciclo."},
]},
{p:"02_Metabolismo_Glucidico_I.pdf",m:1,q:[
{d:"Cosa assorbono esclusivamente le cellule intestinali dei carboidrati della dieta?",o:["Polisaccaridi interi","Solo monosaccaridi","Disaccaridi non idrolizzati","Cellulosa"],r:1,s:"Le cellule intestinali assorbono solo monosaccaridi. I carboidrati della dieta vengono prima scissi nei monosaccaridi costituenti ad opera di specifiche idrolasi."},
{d:"Quale legame glicosidico caratterizza la cellulosa, rendendola non digeribile dall'uomo?",o:["α-1,4 glicosidico","β-1,4 glicosidico","α-1,6 glicosidico","α-1,2 glicosidico"],r:1,s:"La cellulosa presenta legami β-1,4 glicosidici, che gli enzimi umani non sono in grado di scindere (a differenza dei legami α-1,4 dell'amido). Per questo è una fibra non digeribile."},
{d:"Da quali monosaccaridi è costituito il saccarosio e con quale legame?",o:["Galattosio e glucosio, legame β-1,4","Glucosio e fruttosio, legame α-1,2","Due glucosio, legame α-1,4","Due glucosio, legame α-1,6"],r:1,s:"Il saccarosio è formato da glucosio e fruttosio uniti da legame α-1,2 glicosidico. Il lattosio è invece galattosio + glucosio (β-1,4) e il maltosio è glucosio + glucosio (α-1,4)."},
{d:"Quali sono le sedi della digestione dei carboidrati?",o:["Solo lo stomaco","Bocca, lume dell'intestino tenue e cellule epiteliali della mucosa intestinale","Esclusivamente il pancreas","Solo l'intestino crasso"],r:1,s:"La digestione dei carboidrati avviene nella bocca (amilasi salivare), nel lume dell'intestino tenue (amilasi pancreatica) e nelle cellule epiteliali della mucosa intestinale (disaccaridasi)."},
{d:"Quale enzima compie il processo digestivo più consistente dell'amido e che tipo di enzima è?",o:["La lattasi, una β-glicosidasi","L'amilasi pancreatica, un'endoglucosidasi che scinde i legami α-1,4","L'isomaltasi, che scinde i legami β-1,4","La saccarasi, che scinde i legami α-1,6"],r:1,s:"L'amilasi pancreatica svolge il processo digestivo più consistente (quella salivare ha azione molto fugace). È un'endoglucosidasi che scinde i legami α-1,4 glicosidici interni dell'amido."},
{d:"L'α-amilasi NON è in grado di scindere quale tipo di legame?",o:["I legami α-1,4 interni","I legami α-1,6 dei punti di ramificazione (lascia le destrine limite)","I legami terminali dell'amilosio","I legami del maltotriosio"],r:1,s:"L'α-amilasi scinde i legami α-1,4 ma non i legami α-1,6 dei punti di ramificazione, lasciando le destrine limite (circa 30% dei prodotti dall'amilopectina). Le destrine vengono poi scisse dall'isomaltasi."},
{d:"Dove sono localizzate le disaccaridasi intestinali e come è orientato il loro sito attivo?",o:["Nel citosol degli enterociti","Ancorate alle cellule della mucosa intestinale, con il sito attivo esposto nel lume intestinale","Libere nel succo pancreatico","Nella saliva"],r:1,s:"Le disaccaridasi e oligosaccaridasi sono ancorate alle cellule della mucosa intestinale con il sito attivo esposto verso il lume intestinale, dove idrolizzano gli oligosaccaridi prodotti."},
{d:"Quale enzima della mucosa intestinale idrolizza il lattosio e quale legame scinde?",o:["La saccarasi, legame α-1,2","La lattasi, legame β-1,4 glicosidico","La maltasi, legame α-1,4","L'isomaltasi, legame α-1,6"],r:1,s:"La lattasi idrolizza il lattosio scindendo il legame β-1,4 glicosidico, liberando galattosio e glucosio."},
{d:"Quale enzima scinde le destrine limite e quale legame idrolizza?",o:["La maltasi, legame α-1,4","L'isomaltasi, legame α-1,6 glicosidico","La lattasi, legame β-1,4","La saccarasi, legame α-1,2"],r:1,s:"L'isomaltasi scinde le destrine idrolizzando i legami α-1,6 glicosidici (i punti di ramificazione che l'amilasi non riesce a tagliare)."},
{d:"Come si distinguono le deficienze congenite o acquisite delle disaccaridasi?",o:["In acute e croniche","In aspecifiche (assenza di tutte le disaccaridasi) e specifiche (una sola disaccaridasi, es. intolleranza al lattosio)","In ereditarie e infettive","In epatiche e renali"],r:1,s:"Le deficienze possono essere aspecifiche (assenza di tutte le disaccaridasi) o specifiche (deficit di una sola disaccaridasi, come nell'intolleranza al lattosio da carenza di lattasi)."},
{d:"Cosa causa l'intolleranza al lattosio?",o:["Un eccesso di lattasi","Una presenza insufficiente dell'enzima lattasi, che impedisce di digerire lo zucchero del latte","L'assenza di amilasi pancreatica","Una mutazione del gene ALDOB"],r:1,s:"L'intolleranza al lattosio è l'incapacità di digerire lo zucchero del latte e derivati, causata da una presenza insufficiente dell'enzima lattasi."},
{d:"Cosa accade al lattosio non digerito che raggiunge l'intestino crasso nell'intolleranza al lattosio?",o:["Viene assorbito direttamente nel sangue","Viene fermentato dai batteri producendo H2, CO2 e metaboliti, causando gonfiore, diarrea e disidratazione","Viene escreto immodificato senza effetti","Viene convertito in glucosio dal fegato"],r:1,s:"Il lattosio non digerito arriva nell'intestino crasso dove i batteri lo fermentano producendo H2, CO2, H2O e metaboliti, causando gonfiore, diarrea e disidratazione. L'H2 prodotto è misurabile col breath test."},
{d:"Su quale principio si basa il breath test per l'intolleranza al lattosio?",o:["Sulla misurazione del glucosio nel sangue","Sulla misurazione del livello di idrogeno (H2) nel respiro, prodotto dalla fermentazione batterica del lattosio","Sulla misurazione del lattato urinario","Sulla misurazione del pH gastrico"],r:1,s:"Il breath test al lattosio si basa sulla misurazione dell'H2 nel respiro espirato: il lattosio non digerito viene fermentato dai batteri intestinali producendo H2 che passa nel circolo ematico e viene espirato."},
{d:"Come varia l'attività della lattasi nel corso della vita?",o:["Aumenta progressivamente con l'età","È alta nel bambino e tende a diminuire nell'adulto","Rimane costante per tutta la vita","È assente nel neonato e compare nell'adulto"],r:1,s:"L'attività della lattasi è elevata nel bambino (per digerire il latte materno) ma in molti individui tende a diminuire drasticamente nell'adulto, causando l'intolleranza al lattosio."},
{d:"Tramite quale trasportatore vengono assorbiti glucosio e galattosio nel lato luminale dell'enterocita?",o:["GLUT5","SGLUT1 (co-trasporto con Na+)","GLUT2","GLUT4"],r:1,s:"Glucosio e galattosio entrano nell'enterocita dal lato luminale tramite SGLUT1, un co-trasportatore che trasporta il monosaccaride insieme a uno ione sodio (trasporto attivo secondario)."},
{d:"Quale condizione è necessaria affinché SGLUT1 assorba molte molecole di glucosio?",o:["Alte concentrazioni intracellulari di sodio","Il mantenimento di basse concentrazioni intracellulari di sodio garantito dalla pompa Na+/K+ ATPasi basolaterale","Alte concentrazioni di glucosio nel citosol","L'assenza di ATP"],r:1,s:"Per far entrare molto glucosio è necessario mantenere basse le concentrazioni intracellulari di sodio: ciò è garantito dalla pompa Na+/K+ ATPasi presente nella membrana basolaterale, che crea il gradiente di Na+."},
{d:"Quale trasportatore assorbe il fruttosio nel lato luminale dell'enterocita?",o:["SGLUT1","GLUT5","GLUT2","GLUT4"],r:1,s:"Il fruttosio viene assorbito dal lato luminale dell'enterocita tramite GLUT5, un trasportatore specifico per il fruttosio (non per il glucosio), per diffusione facilitata."},
{d:"Quali ruoli centrali svolge il glucosio nel metabolismo?",o:["Solo precursore di proteine","Combustibile universale (unico per il cervello) e precursore di altri glucidi e molecole non glucidiche","Esclusivamente substrato per la sintesi di acidi grassi","Solo costituente delle membrane"],r:1,s:"Il glucosio è il monosaccaride più abbondante assorbito ed è combustibile universale (l'unico per il cervello in condizioni normali) e precursore di altri glucidi e di molecole non glucidiche."},
{d:"Qual è la definizione di glicemia e i valori tipici in soggetti sani?",o:["La quantità di glicogeno epatico; 200-300 mg/100ml","La concentrazione di glucosio nel sangue; nella giornata si mantiene tra circa 80 e 130 mg/100ml","La concentrazione di lattato; 10-20 mg/100ml","La concentrazione di insulina; 50-60 mg/100ml"],r:1,s:"La glicemia è la concentrazione di glucosio nel sangue. In soggetti sani si mantiene durante la giornata tra circa 80 e 130 mg/100ml (a digiuno fisiologico 70-90, dopo un pasto sale a 130 in 40-60 min)."},
{d:"Cos'è l'Indice Glicemico (IG) di un alimento?",o:["La quantità totale di calorie dell'alimento","Un indicatore della rapidità con cui aumentano i livelli di glucosio nel sangue dopo l'ingestione","Il contenuto di fibre dell'alimento","La percentuale di proteine presenti"],r:1,s:"L'Indice Glicemico è un indicatore della rapidità con cui aumentano i livelli di glucosio nel sangue dopo l'ingestione di un alimento. Alimenti a basso IG causano piccole fluttuazioni glicemiche/insuliniche e minore effetto lipogenico."},
{d:"Quale conseguenza hanno gli alimenti a basso indice glicemico?",o:["Provocano grandi picchi insulinici e maggiore lipogenesi","Determinano piccole fluttuazioni del glucosio ematico e dell'insulina, con minore effetto lipogenico","Aumentano rapidamente la glicemia","Non influenzano l'insulina"],r:1,s:"Gli alimenti a basso indice glicemico determinano solo piccole fluttuazioni nei livelli del glucosio ematico e quindi dell'insulina, con un minore effetto lipogenico (meno tendenza ad accumulare grasso)."},
{d:"Cosa sono i trasportatori GLUT?",o:["Enzimi che fosforilano il glucosio","Trasportatori proteici della membrana plasmatica che facilitano il passaggio del glucosio nelle cellule, con isoforme tessuto-specifiche","Ormoni che regolano la glicemia","Proteine di deposito del glucosio"],r:1,s:"I GLUT (GLUcose Transporters) sono trasportatori proteici della membrana plasmatica che facilitano (diffusione facilitata) il passaggio del glucosio nelle cellule. Ne esistono diverse isoforme in diversi tessuti."},
{d:"Quale trasportatore del glucosio è sensibile all'insulina ed è presente in muscolo scheletrico e adipociti?",o:["GLUT1","GLUT4","GLUT2","GLUT5"],r:1,s:"GLUT4 (in muscolo scheletrico, adipociti e muscolo cardiaco) trasporta il glucosio con elevata affinità (Ka 2mM) ed è sensibile all'insulina: l'insulina ne promuove la traslocazione in membrana in muscolo e tessuto adiposo."},
{d:"Quale trasportatore funziona come 'sensore di glucosio' per le cellule β del pancreas ed è a bassa affinità?",o:["GLUT1","GLUT2 (Ka ~10 mM)","GLUT3","GLUT4"],r:1,s:"GLUT2 (fegato, cellule β pancreatiche, intestino tenue, rene) è un trasportatore a bassa affinità (Ka 10 mM) e funziona da sensore di glucosio per le cellule β del pancreas, regolando la secrezione insulinica in base alla glicemia."},
{d:"Qual è il principale trasportatore di glucosio dei neuroni?",o:["GLUT1","GLUT3 (elevata affinità, Ka 1mM)","GLUT2","GLUT5"],r:1,s:"GLUT3 (cervello, placenta, rene) trasporta il glucosio con elevata affinità (Ka 1mM) ed è il principale trasportatore dei neuroni, garantendo l'apporto di glucosio anche a basse glicemie."},
{d:"In quale forma il glucosio può attraversare la membrana plasmatica e in quale forma si trova all'interno delle cellule?",o:["Attraversa come glucosio-6-fosfato; all'interno è glucosio libero","Attraversa come glucosio libero; all'interno è nella forma metabolicamente attiva di glucosio-6-fosfato","Attraversa e resta sempre come glucosio libero","Attraversa come fruttosio-6-fosfato"],r:1,s:"Il glucosio attraversa la membrana solo in forma libera. All'interno della cellula viene fosforilato a glucosio-6-fosfato, la sua forma metabolicamente attiva, che non può più uscire (resta intrappolato)."},
{d:"Perché la fosforilazione del glucosio a glucosio-6-fosfato è irreversibile?",o:["Perché libera CO2","Perché utilizza un legame anidridico dell'ATP (7,5 kcal/mol) per formare un legame estereo (3,3 kcal/mol)","Perché produce NADH","Perché richiede FAD"],r:1,s:"La reazione è irreversibile (ΔG'°=-16,7 kJ/mol) perché utilizza l'energia di un legame anidridico dell'ATP (7,5 kcal/mol) per formare un legame estereo più povero di energia (3,3 kcal/mol): la differenza di energia rende il processo termodinamicamente unidirezionale."},
{d:"Quale enzima permette la trasformazione del glucosio-6-fosfato in glucosio libero e dove è presente?",o:["L'esochinasi, presente in tutti i tessuti","La glucosio-6-fosfato fosfatasi, enzima esclusivamente epatico (e renale)","La glucochinasi, nel muscolo","La PFK-1, nel cervello"],r:1,s:"La sola possibilità di riconvertire il G-6-P in glucosio libero è l'idrolisi del radicale fosforico catalizzata dalla glucosio-6-fosfato fosfatasi, enzima esclusivamente epatico (e renale). Per questo solo fegato e rene possono rilasciare glucosio nel sangue."},
{d:"Quale caratteristica distingue l'esochinasi IV (glucochinasi) dalle altre esochinasi?",o:["Ha una Km molto bassa (<0.1mM) ed è inibita da glucosio-6-P","Ha una Km elevata (~10mM), è specifica per il glucosio, è presente solo nel fegato, NON è inibita da glu-6-P ed è inducibile","È presente in tutti i tessuti","Ha bassa affinità ma è inibita dal suo prodotto"],r:1,s:"La glucochinasi (esochinasi IV) ha Km elevata (~10mM, vicina ai valori di glicemia), è specifica per il glucosio, presente solo nel fegato, NON è inibita dal glucosio-6-P ed è inducibile. Le esochinasi I-III hanno bassa Km (<0.1mM) e sono inibite dal glu-6-P."},
{d:"Perché la presenza della glucochinasi è importante per il ruolo del fegato nella regolazione della glicemia?",o:["Perché fosforila il glucosio anche a basse glicemie","Perché, avendo Km alta (~10mM), capta e fosforila il glucosio in modo proporzionale alla glicemia, fosforilandolo efficacemente solo quando la glicemia è elevata","Perché è inibita dal glucosio-6-fosfato","Perché è attiva solo nel digiuno"],r:1,s:"La glucochinasi, con la sua Km alta (~10mM), non è satura ai normali livelli di glicemia: la sua attività aumenta proporzionalmente alla glicemia. Così il fegato fosforila molto glucosio solo quando questo è abbondante (dopo i pasti), regolando la glicemia."},
{d:"Quali sono le possibili vie metaboliche del glucosio-6-fosfato?",o:["Solo la glicolisi","Glicogenosintesi (via glucosio-1-P), via dei pentoso fosfati (ribosio-5-P + NADPH), glicolisi, o defosforilazione a glucosio libero","Solo la sintesi di glicogeno","Esclusivamente la conversione in fruttosio"],r:1,s:"Il glucosio-6-P è un punto di snodo: può andare verso glicogenosintesi (via glucosio-1-P), via dei pentoso fosfati (ribosio-5-P e NADPH), glicolisi (via fruttosio-6-P) o essere defosforilato a glucosio libero. La scelta dipende dal tessuto e dallo stato nutrizionale/ormonale."},
{d:"Qual è la reazione complessiva della glicolisi?",o:["Glucosio → 2 lattato + 2 ATP","Glucosio + 2 NAD+ + 2 ADP + 2 Pi → 2 Piruvato + 2 NADH + 2H+ + 2 ATP","Glucosio + O2 → 6 CO2 + 6 H2O","Glucosio + ATP → glucosio-6-fosfato + ADP"],r:1,s:"La reazione complessiva della glicolisi è: Glucosio + 2 NAD+ + 2 ADP + 2 Pi → 2 Piruvato + 2 NADH + 2H+ + 2 ATP. Avviene nel citosol di tutte le cellule umane."},
{d:"Dove avviene la glicolisi e da quante reazioni è composta?",o:["Nella matrice mitocondriale, 8 reazioni","Nel citoplasma (citosol) di tutte le cellule, 10 reazioni","Nel reticolo endoplasmatico, 12 reazioni","Nel nucleo, 5 reazioni"],r:1,s:"La glicolisi avviene nel citoplasma (citosol) di tutte le cellule umane ed è costituita da 10 reazioni enzimatiche."},
{d:"Come si suddividono le due fasi della glicolisi e qual è la resa netta?",o:["Fase ossidativa (consuma 4 ATP) e fase preparatoria (produce 2 ATP); resa netta -2 ATP","Fase preparatoria/di investimento (consuma 2 ATP) e fase ossidativa/di recupero (produce 4 ATP + 2 NADH); resa netta di 2 ATP per glucosio","Entrambe le fasi consumano ATP; resa netta 0","Fase aerobia e fase anaerobia; resa netta 38 ATP"],r:1,s:"La I fase preparatoria (investimento energetico) consuma 2 ATP. La II fase ossidativa (recupero energetico) produce 2 NADH(H+) e 4 ATP. La resa netta è quindi di 2 ATP per molecola di glucosio."},
{d:"Perché tutti gli intermedi della glicolisi sono fosforilati?",o:["Per renderli più solubili in acqua","Perché a pH 7.4 i fosfati sono ionizzati e in queste condizioni non possono attraversare i bilayer lipidici (restano intrappolati nella cellula)","Per aumentarne il peso molecolare","Per facilitarne l'espulsione dalla cellula"],r:1,s:"Tutti gli intermedi glicolitici sono fosforilati perché a pH 7.4 i fosfati sono ionizzati (carichi negativamente) e non possono attraversare i bilayer lipidici delle membrane: gli intermedi restano così intrappolati nella cellula."},
{d:"Quale enzima catalizza la 2° reazione della glicolisi e di che tipo è?",o:["L'aldolasi, una liasi","La fosfoglucosio (fosfoesoso) isomerasi, che isomerizza glucosio-6-P a fruttosio-6-P","L'esochinasi, una chinasi","L'enolasi, una liasi"],r:1,s:"La 2° reazione è catalizzata dalla fosfoglucosio isomerasi (fosfoesoso isomerasi), che isomerizza il glucosio-6-fosfato (aldoso) in fruttosio-6-fosfato (chetoso). Questa isomerizzazione è necessaria per mandare avanti la glicolisi."},
{d:"Quale enzima catalizza la 3° reazione della glicolisi e perché è importante?",o:["L'esochinasi; perché fosforila il glucosio","La fosfofruttochinasi-1 (PFK-1); è irreversibile e rappresenta il maggiore punto di controllo della glicolisi","L'enolasi; perché disidrata il substrato","La piruvato chinasi; perché produce ATP"],r:1,s:"La PFK-1 catalizza la fosforilazione del fruttosio-6-P a fruttosio-1,6-bisfosfato. È una reazione irreversibile (ΔG'°=-14,2 kJ/mol) e rappresenta il maggiore punto di controllo della glicolisi: è un enzima tetramerico allosterico."},
{d:"Come agisce l'ATP sulla PFK-1?",o:["È un attivatore allosterico","È un effettore allosterico negativo: si lega a un sito diverso dal catalitico e ad alte concentrazioni diminuisce l'affinità dell'enzima per il fruttosio-6-P","È il substrato che viene fosforilato","Non ha alcun effetto sulla PFK-1"],r:1,s:"L'ATP, pur essendo substrato, agisce anche come effettore allosterico negativo legandosi a un sito diverso dal catalitico: ad alte concentrazioni (surplus energetico) diminuisce l'affinità dell'enzima per il fruttosio-6-P, rallentando la glicolisi."},
{d:"Quali sono gli effettori allosterici della PFK-1?",o:["Attivata da ATP e citrato","Inibita da ATP e citrato; attivata da AMP, ADP e fruttosio-2,6-bisfosfato","Inibita solo da AMP","Attivata solo dal NADH"],r:1,s:"La PFK-1 è un enzima allosterico plurivalente: è inibita da ATP e citrato (segnali di surplus energetico) e attivata da AMP, ADP (deficit energetico) e dal fruttosio-2,6-bisfosfato."},
{d:"Qual è il più potente attivatore della PFK-1 a livello epatico, anche in presenza di ATP?",o:["Il citrato","Il fruttosio-2,6-bisfosfato, che agisce a concentrazioni 10 volte inferiori rispetto agli altri regolatori","L'AMP","Il glucosio-6-fosfato"],r:1,s:"A livello epatico il più potente attivatore della PFK-1, anche in presenza di ATP, è il fruttosio-2,6-bisfosfato, la cui azione si manifesta a concentrazioni 10 volte inferiori rispetto agli altri regolatori (ATP, AMP, citrato)."},
{d:"Che tipo di enzima è la PFK-2 e quali attività possiede?",o:["Un enzima monofunzionale solo chinasico","Un enzima bifunzionale (tandem) con attività sia chinasica (PFK-2) che fosfatasica (FBPasi-2) e un dominio regolatorio con serina fosforilabile","Un enzima esclusivamente fosfatasico","Un enzima identico alla PFK-1"],r:1,s:"La PFK-2 è un enzima bifunzionale (tandem) con due siti catalitici: possiede sia attività chinasica (PFK-2, produce fruttosio-2,6-bisfosfato) che fosfatasica (FBPasi-2, lo degrada) e un dominio regolatorio dato da una serina fosforilabile."},
{d:"Cosa determina il funzionamento dell'enzima tandem come PFK-2 (chinasi) oppure come FBPasi-2 (fosfatasi)?",o:["La concentrazione di ossigeno","Lo stato di fosforilazione dell'enzima, che dipende dallo stato ormonale","La temperatura corporea","Il pH del citosol"],r:1,s:"Il funzionamento come chinasi (PFK-2) o fosfatasi (FBPasi-2) dipende dallo stato di fosforilazione dell'enzima tandem, a sua volta determinato dallo stato ormonale (insulina vs glucagone)."},
{d:"A livello epatico, cosa accade quando il glucagone fa fosforilare la PFK-2?",o:["Si attiva il dominio chinasico e aumenta il F-2,6-BP, stimolando la glicolisi","Il dominio chinasico è inattivato (da una chinasi cAMP-dipendente): l'assenza di fruttosio-2,6-bisfosfato rallenta la glicolisi e favorisce la sintesi di glucosio (gluconeogenesi)","Non cambia nulla","Si degrada l'enzima"],r:1,s:"Il glucagone attiva una chinasi cAMP-dipendente (PKA) che fosforila e inattiva il dominio chinasico della PFK-2. La conseguente assenza di fruttosio-2,6-bisfosfato rallenta la glicolisi e favorisce la gluconeogenesi (logico durante il digiuno)."},
{d:"Come agisce l'insulina sulla PFK-2 a livello epatico?",o:["La fa fosforilare, inibendo la glicolisi","Stimola la defosforilazione e attivazione del dominio chinasico (PFK-2): aumenta il fruttosio-2,6-bisfosfato che stimola la glicolisi","Non ha effetto","Stimola la gluconeogenesi"],r:1,s:"L'insulina (segnale di abbondanza di glucosio) stimola la defosforilazione e attivazione del dominio chinasico della PFK-2, facendola funzionare come fosfofruttochinasi di tipo 2: aumenta il F-2,6-BP che attiva la PFK-1 stimolando la glicolisi."},
{d:"Quale enzima catalizza la 4° reazione della glicolisi (scissione del fruttosio-1,6-bisfosfato) e cosa produce?",o:["La PFK-1; produce piruvato","L'aldolasi; scinde il fruttosio-1,6-bisfosfato in diidrossiacetone fosfato e gliceraldeide-3-fosfato","L'enolasi; produce fosfoenolpiruvato","L'esochinasi; produce glucosio-6-P"],r:1,s:"L'aldolasi catalizza la scissione (aldolica) reversibile del fruttosio-1,6-bisfosfato in due triosi fosfato: diidrossiacetone fosfato (DHAP) e gliceraldeide-3-fosfato (G3P). L'equilibrio è spostato a destra dalla successiva demolizione della G3P."},
{d:"Quale enzima catalizza la 5° reazione (interconversione dei triosi fosfato)?",o:["L'aldolasi","La trioso fosfato isomerasi, che converte il diidrossiacetone fosfato in gliceraldeide-3-fosfato","La fosfoglicerato mutasi","L'enolasi"],r:1,s:"La trioso fosfato isomerasi converte il diidrossiacetone fosfato in gliceraldeide-3-fosfato. Così da 1 molecola di fruttosio-1,6-bisfosfato si ottengono in totale 2 molecole di G3P, le uniche a proseguire nella glicolisi."},
{d:"Cosa produce la 6° reazione della glicolisi, catalizzata dalla gliceraldeide-3-fosfato deidrogenasi (GAPDH)?",o:["Piruvato e ATP","1,3-bisfosfoglicerato e NADH, conservando l'energia dell'ossidazione dell'aldeide in un legame fosfoanidridico ad alta energia","Glucosio-6-fosfato e ADP","Fosfoenolpiruvato e H2O"],r:1,s:"La GAPDH ossida la gliceraldeide-3-fosfato (con NAD+→NADH) e aggiunge un fosfato inorganico, formando 1,3-bisfosfoglicerato. Conserva l'energia dell'ossidazione del C aldeidico in un legame fosfoanidridico ad alta energia, utile per la reazione successiva."},
{d:"Quale enzima catalizza la 7° reazione della glicolisi e cosa produce?",o:["La piruvato chinasi; produce piruvato","La fosfoglicerato chinasi; trasferisce il gruppo fosforico dall'1,3-bisfosfoglicerato all'ADP formando 3-fosfoglicerato e ATP (prima fosforilazione a livello del substrato)","L'enolasi; produce PEP","L'aldolasi; produce triosi fosfato"],r:1,s:"La fosfoglicerato chinasi trasferisce il gruppo fosforico dall'1,3-bisfosfoglicerato all'ADP, formando 3-fosfoglicerato e ATP (ΔG'°=-18,8 kJ/mol). È la prima reazione di sintesi di ATP per fosforilazione a livello del substrato."},
{d:"Perché la reazione della GAPDH (endoergonica) può comunque procedere nella glicolisi?",o:["Perché consuma ATP","Perché è accoppiata alla reazione fortemente esoergonica della fosfoglicerato chinasi: la somma delle due (GA3P+Pi+NAD+ +ADP → 3PG+NADH+ATP) ha ΔG°' negativo (-12,1 kJ/mol)","Perché produce CO2","Perché avviene nel mitocondrio"],r:1,s:"La reazione della GAPDH è endoergonica (ΔG°'=+6,7 kJ/mol), ma il successivo trasferimento del gruppo fosforico dall'1,3-BPG all'ADP (fosfoglicerato chinasi) è fortemente esoergonico (-18,8 kJ/mol). L'accoppiamento rende la reazione complessiva esoergonica (-12,1 kJ/mol) e quindi possibile."},
{d:"Quale enzima catalizza la 8° reazione e cosa usa per funzionare?",o:["L'enolasi, che usa acqua","La fosfoglicerato mutasi, che converte 3-fosfoglicerato in 2-fosfoglicerato usando un piccolo pool di 2,3-bisfosfoglicerato (rigenerato dal ciclo)","La piruvato chinasi, che usa ADP","La GAPDH, che usa NAD+"],r:1,s:"La fosfoglicerato mutasi sposta il fosfato dalla posizione 3 alla 2, convertendo 3-fosfoglicerato in 2-fosfoglicerato. Usa un piccolo pool di 2,3-bisfosfoglicerato (un residuo di His si fosforila), che viene continuamente rigenerato dal ciclo stesso."},
{d:"Quale enzima catalizza la 9° reazione della glicolisi e cosa produce?",o:["La fosfoglicerato mutasi; produce 3-fosfoglicerato","L'enolasi; deidrata il 2-fosfoglicerato a fosfoenolpiruvato (PEP), un enolfosfato ad elevato potenziale di trasferimento del gruppo fosforico","La piruvato chinasi; produce piruvato","L'aldolasi; produce triosi"],r:1,s:"L'enolasi catalizza la deidratazione del 2-fosfoglicerato (un β-idrossiacido instabile) a fosfoenolpiruvato (PEP), un composto acido α-β insaturo (enolfosfato) con elevatissimo potenziale di trasferimento del gruppo fosforico."},
{d:"Quale enzima catalizza la 10° e ultima reazione della glicolisi?",o:["L'enolasi","La piruvato chinasi, che trasferisce il gruppo fosforico dal PEP all'ADP formando piruvato e ATP (reazione irreversibile)","La fosfoglicerato chinasi","La GAPDH"],r:1,s:"La piruvato chinasi (chiamata impropriamente così) catalizza l'ultima reazione, irreversibile (ΔG°'=-31,4 kJ/mol): trasferisce il gruppo fosforico dal PEP all'ADP formando piruvato e ATP (seconda fosforilazione a livello del substrato)."},
{d:"Cosa 'traina' termodinamicamente la reazione della piruvato chinasi rendendola irreversibile?",o:["Il consumo di NADH","La tautomerizzazione spontanea del piruvato dalla forma enolica (instabile) alla forma chetonica più stabile","L'idrolisi dell'ATP","La produzione di CO2"],r:1,s:"Il trasferimento del fosfato genera dapprima la forma enolica del piruvato, che spontaneamente tautomerizza alla forma chetonica più stabile. Questo secondo passaggio è uno degli eventi che trainano termodinamicamente la reazione, rendendola irreversibile."},
{d:"Quali sono le tre reazioni irreversibili della glicolisi che rappresentano i punti di regolazione?",o:["Aldolasi, enolasi e GAPDH","Esochinasi/glucochinasi, fosfofruttochinasi-1 (PFK-1) e piruvato chinasi","Fosfoglicerato chinasi, fosfoglicerato mutasi e trioso fosfato isomerasi","Fosfoglucosio isomerasi, aldolasi e enolasi"],r:1,s:"Le tre reazioni irreversibili che rappresentano i punti di regolazione della glicolisi sono catalizzate da: esochinasi/glucochinasi (1°), PFK-1 (3°, principale) e piruvato chinasi (10°)."},
{d:"Come è regolata la piruvato chinasi?",o:["Attivata da ATP e acetil-CoA","Inibita da ATP (allosterico) e acetil-CoA (da prodotto); a livello epatico regolata per fosforilazione/defosforilazione (la forma fosforilata da glucagone/PKA è inattiva)","Attivata solo dal NADH","Non subisce alcuna regolazione"],r:1,s:"La piruvato chinasi è inibita da ATP (allosterico) e acetil-CoA (inibizione da prodotto) e dagli acidi grassi a catena lunga. A livello epatico è regolata per fosforilazione (glucagone/PKA la fosforila inattivandola) ed è attivata dal fruttosio-1,6-bisfosfato."},
{d:"Quali sono le funzioni tessuto-specifiche della glicolisi nel cervello?",o:["Solo sintesi di trigliceridi","Ruolo fondamentale: il cervello dipende quasi esclusivamente dal glucosio per i suoi bisogni energetici (circa 120 g di glucosio/die)","Sintesi di acidi grassi","Produzione di lattato"],r:1,s:"La glicolisi ha un ruolo fondamentale nel cervello, che dipende quasi esclusivamente dal glucosio per i suoi bisogni energetici, consumando circa 120 g di glucosio al giorno."},
{d:"Su quale principio biochimico si basa l'uso del [18F]FDG nella PET per la diagnosi tumorale?",o:["L'FDG è tossico solo per le cellule tumorali","L'FDG (analogo del glucosio con fluoro al posto dell'OH in C2) entra nelle cellule e viene fosforilato, ma non è riconosciuto dall'enzima della 2° reazione: resta intrappolato e si accumula nelle cellule tumorali (avide di glucosio)","L'FDG si lega al DNA tumorale","L'FDG blocca la prima reazione della glicolisi"],r:1,s:"Il [18F]FDG è un analogo del glucosio con un atomo di fluoro al posto dell'OH in posizione C2. Entra nelle cellule e inizia la glicolisi (viene fosforilato), ma non è riconosciuto dall'enzima della 2° reazione (fosfoglucosio isomerasi): rimane intrappolato. Le cellule tumorali, molto avide di glucosio, lo accumulano permettendone la localizzazione."},
{d:"Quali sono i destini metabolici del piruvato in condizioni anaerobiche?",o:["Ossidazione mitocondriale a CO2","Fermentazione alcolica (lieviti → etanolo + CO2) o fermentazione lattica (eritrocita e muscolo in intensa contrazione → acido lattico)","Sintesi diretta di glucosio","Conversione in acetil-CoA"],r:1,s:"In condizioni anaerobiche il piruvato va incontro a fermentazione alcolica (nei lieviti, producendo etanolo e CO2) o fermentazione lattica (negli eritrociti e nel muscolo in intensa contrazione, producendo acido lattico). In aerobiosi viene invece ossidato nel mitocondrio."},
{d:"Qual è la funzione principale della fermentazione (lattica o alcolica) in condizioni anaerobiche?",o:["Produrre grandi quantità di ATP","Rigenerare il NAD+ necessario alla GAPDH per far continuare la glicolisi","Sintetizzare glucosio","Eliminare la CO2"],r:1,s:"In anaerobiosi la fermentazione è necessaria per rigenerare il NAD+ (a partire dal NADH prodotto dalla GAPDH): senza NAD+ la glicolisi si bloccherebbe. La fermentazione permette quindi alla glicolisi di continuare anche in assenza di ossigeno."},
{d:"Quali enzimi sono coinvolti nella fermentazione alcolica del piruvato nei lieviti?",o:["Lattato deidrogenasi soltanto","Piruvato decarbossilasi (piruvato → acetaldeide + CO2) e alcol deidrogenasi (acetaldeide + NADH → etanolo + NAD+)","Piruvato deidrogenasi e citrato sintasi","Aldolasi e enolasi"],r:1,s:"Nella fermentazione alcolica il piruvato è prima decarbossilato ad acetaldeide (+ CO2) dalla piruvato decarbossilasi, poi l'acetaldeide è ridotta a etanolo dall'alcol deidrogenasi, che riossida il NADH a NAD+."},
{d:"Quale enzima catalizza la fermentazione lattica e cosa permette?",o:["L'alcol deidrogenasi; produce etanolo","La lattato deidrogenasi; riduce il piruvato a lattato riossidando il NADH a NAD+, permettendo alla glicolisi di proseguire senza coinvolgere la respirazione","La piruvato decarbossilasi; produce CO2","La piruvato deidrogenasi; produce acetil-CoA"],r:1,s:"La lattato deidrogenasi riduce il piruvato a lattato, riossidando il NADH a NAD+. Questo rigenera il NAD+ necessario alla GAPDH, permettendo alla cellula di produrre ATP con la glicolisi senza il coinvolgimento della respirazione cellulare."},
{d:"Cosa caratterizza l'acidosi lattica?",o:["Un eccesso di ossigeno nei tessuti","Si manifesta quando l'ossigenazione dei tessuti è inadeguata e le cellule ricavano ATP dalla glicolisi anaerobia: lattato prodotto > lattato utilizzato, con diminuzione del pH","Un aumento del pH ematico","Una carenza di glucosio"],r:1,s:"L'acidosi lattica si manifesta quando l'ossigenazione dei tessuti è inadeguata e le cellule ricavano ATP dalla glicolisi anaerobia. Il lattato prodotto supera quello utilizzato e la sua ionizzazione abbassa il pH. Si tratta con bicarbonato, tiamina (ripristino PDH) e riossigenazione."},
{d:"Quale complesso enzimatico catalizza la trasformazione del piruvato in acetil-CoA in condizioni aerobiche?",o:["La piruvato carbossilasi","Il complesso della piruvato deidrogenasi (PDH)","La lattato deidrogenasi","La citrato sintasi"],r:1,s:"In aerobiosi il piruvato viene trasportato nei mitocondri e trasformato in acetil-CoA dal complesso enzimatico della piruvato deidrogenasi (PDH), attraverso una decarbossilazione ossidativa che produce anche CO2 e NADH."},
{d:"Da quanti enzimi e coenzimi è costituito il complesso della piruvato deidrogenasi e dove è localizzato?",o:["1 enzima e 1 coenzima, nel citosol","3 enzimi e 5 coenzimi, localizzato nella matrice mitocondriale (MMI), che catalizzano 4 reazioni in sequenza senza rilascio di intermedi","8 enzimi, nella membrana esterna","5 enzimi e 3 coenzimi, nel reticolo"],r:1,s:"Il complesso della PDH è un complesso multienzimatico costituito da 3 enzimi (E1 piruvato deidrogenasi, E2 diidrolipoil transacetilasi, E3 diidrolipoil deidrogenasi) e 5 coenzimi, che catalizzano 4 reazioni in sequenza senza rilasciare gli intermedi."},
{d:"Quali sono i 5 coenzimi/cofattori del complesso della piruvato deidrogenasi?",o:["Biotina, NADP+, FMN, CoQ, eme","Tiamina pirofosfato (TPP), acido lipoico (lipoammide), Coenzima A (CoA), FAD e NAD+","Solo TPP e FAD","ATP, GTP, NADPH, Mg2+ e Ca2+"],r:1,s:"I 5 cofattori del complesso PDH sono: TPP (legato a E1, decarbossila il piruvato), acido lipoico/lipoammide (legato a E1, accetta l'idrossietile), CoA (substrato di E2, accetta il gruppo acetilico), FAD (legato a E3) e NAD+ (substrato di E3)."},
{d:"Perché gli organismi NON possono produrre carboidrati a partire dall'acetil-CoA?",o:["Perché l'acetil-CoA è tossico","Perché la reazione della piruvato deidrogenasi è irreversibile (non si può riconvertire acetil-CoA in piruvato)","Perché manca il glucosio di partenza","Perché l'acetil-CoA non entra nel mitocondrio"],r:1,s:"L'irreversibilità della reazione della piruvato deidrogenasi giustifica il fatto che gli organismi NON possono produrre carboidrati (glucosio) a partire dall'acetil-CoA: non esiste una via per riconvertire l'acetil-CoA in piruvato."},
{d:"Come è regolato il complesso della piruvato deidrogenasi tramite la sua chinasi?",o:["La chinasi è inibita da ATP e attivata da ADP","La chinasi (che fosforila e inattiva la PDH) è stimolata da ATP, NADH e acetil-CoA e inibita da CoASH, NAD+, ADP e piruvato","La chinasi è attivata solo dal Ca2+","La chinasi non è regolata"],r:1,s:"La PDH chinasi (che fosforila e inattiva E1) è stimolata da ATP, NADH e acetil-CoA (segnali di abbondanza energetica) e inibita da CoASH, NAD+, ADP e piruvato. La fosfatasi (che riattiva la PDH) è stimolata da Mg2+ e Ca2+."},
{d:"Perché il NADH citosolico prodotto dalla glicolisi necessita di sistemi navetta?",o:["Perché viene degradato nel citosol","Perché il NADH(H+) NON può attraversare la membrana mitocondriale interna, ma deve essere riossidato a livello mitocondriale in condizioni aerobiche","Perché è troppo grande per uscire dalla cellula","Perché si trasforma spontaneamente in FADH2"],r:1,s:"Il NADH(H+) prodotto nel citosol dalla glicolisi deve essere riossidato a livello mitocondriale (in aerobiosi), ma non può attraversare direttamente la membrana mitocondriale interna. Per questo il trasporto dei suoi elettroni sfrutta i sistemi navetta (shuttle)."},
{d:"Quali sono i due sistemi navetta per gli equivalenti riducenti del NADH citosolico?",o:["Navetta del citrato e navetta del piruvato","Navetta del glicerolo-3-fosfato e navetta del malato-aspartato","Navetta dell'ossalacetato e navetta del lattato","Navetta della carnitina e navetta dell'ATP"],r:1,s:"I due sistemi navetta sono: la navetta del glicerolo-3-fosfato (attiva in cervello e muscolo scheletrico) e la navetta del malato-aspartato (prevalente nel fegato, presente anche in rene e cuore)."},
{d:"Quali caratteristiche distinguono la navetta malato-aspartato?",o:["Produce 1,5 ATP per NADH e funziona in una sola direzione","È prevalente nel fegato (presente anche in rene e cuore), rende 2,5 ATP per NADH (ossidazione diretta del NADH in catena) e può trasportare equivalenti riducenti in entrambe le direzioni","È attiva solo nel cervello","Non coinvolge la malato deidrogenasi"],r:1,s:"La navetta malato-aspartato è prevalente nel fegato (anche rene e cuore), rende 2,5 ATP per NADH (perché il NADH viene rigenerato nel mitocondrio e ossidato direttamente in catena) ed è bidirezionale: può fornire equivalenti riducenti anche al citoplasma (es. per la gluconeogenesi)."},
{d:"Quali caratteristiche distinguono la navetta del glicerolo-3-fosfato?",o:["Rende 2,5 ATP per NADH ed è bidirezionale","Attiva in cervello e muscolo scheletrico, rende 1,5 ATP per NADH (gli elettroni passano al FAD formando FADH2), funziona in una sola direzione (citoplasma → mitocondrio)","È prevalente nel fegato","Non coinvolge il diidrossiacetone fosfato"],r:1,s:"La navetta del glicerolo-3-fosfato è attiva in cervello e muscolo scheletrico, rende solo 1,5 ATP per NADH (gli elettroni vengono trasferiti al FAD della glicerolo-3-P deidrogenasi mitocondriale, formando FADH2) e funziona in una sola direzione: dal citoplasma al mitocondrio."},
{d:"Da cosa è indotta la glicerolo-3-fosfato deidrogenasi mitocondriale e cosa comporta la sua assenza in alcune cellule tumorali?",o:["Dall'insulina; la sua assenza blocca la glicolisi","Dagli ormoni tiroidei; la sua assenza in alcune cellule tumorali promuove la glicolisi 'anaerobia'","Dal glucagone; la sua assenza promuove la gluconeogenesi","Dal cortisolo; la sua assenza non ha effetti"],r:1,s:"La glicerolo-3-fosfato deidrogenasi mitocondriale è indotta dagli ormoni tiroidei. La sua assenza in alcune cellule tumorali favorisce la glicolisi 'anaerobia' (le cellule non riescono a riossidare efficacemente il NADH per via mitocondriale)."},
{d:"Su cosa si basa l'operatività dei sistemi navetta?",o:["Sulla presenza di ossigeno e ATP","Sulla presenza dello stesso enzima sia nel citosol che nel mitocondrio, e sulla capacità dei metaboliti di varcare la membrana mitocondriale interna","Sull'attività della pompa Na+/K+","Sulla degradazione del NADH"],r:1,s:"I sistemi navetta funzionano grazie a: (1) presenza dello stesso enzima (es. malato deidrogenasi o glicerolo-3-P deidrogenasi) sia nel citosol che nel mitocondrio, e (2) capacità dei metaboliti (malato, glicerolo-3-P) di varcare la membrana mitocondriale interna."},
{d:"Qual è la resa energetica totale della glicolisi aerobia (ossidazione completa del glucosio)?",o:["Solo 2 ATP","Circa 30-32 ATP totali, di gran lunga maggiore dei 2 ATP della glicolisi anaerobia","Esattamente 38 ATP sempre","Circa 12 ATP"],r:1,s:"La glicolisi aerobia (ossidazione completa del glucosio) rende circa 30-32 ATP totali: 2 dalla glicolisi, 3-5 dal NADH citosolico (in base al sistema navetta), 5 dai 2 NADH della PDH e 20 dal ciclo di Krebs. È molto più efficiente dei soli 2 ATP della glicolisi anaerobia."},
{d:"Come viene metabolizzato il galattosio derivante dal lattosio?",o:["Viene escreto immodificato","Viene assorbito da SGLUT1, trasportato al fegato tramite GLUT2 e convertito in intermedi della glicolisi (interconversione galattosio ⇄ glucosio)","Viene trasformato direttamente in acidi grassi","Viene assorbito da GLUT5"],r:1,s:"Il galattosio (dalla digestione del lattosio) viene assorbito dall'enterocita tramite SGLUT1, trasportato al fegato attraverso GLUT2 e convertito in intermedi della glicolisi. Esiste un'interconversione galattosio ⇄ glucosio."},
{d:"Come viene fosforilato il fruttosio nel fegato rispetto al muscolo?",o:["In entrambi dall'esochinasi a fruttosio-6-P","Nel muscolo dall'esochinasi a fruttosio-6-P (favorita da bassa [glucosio]); nel fegato da una specifica fruttochinasi (perché l'esochinasi ha scarsa affinità per il fruttosio)","In entrambi dalla glucochinasi","Nel fegato dall'esochinasi e nel muscolo dalla fruttochinasi"],r:1,s:"Nel muscolo il fruttosio è fosforilato a fruttosio-6-P dall'esochinasi (la bassa [glucosio] rende il fruttosio competitivo). Nel fegato l'esochinasi ha scarsa affinità per il fruttosio, che viene quindi fosforilato a fruttosio-1-P da una chinasi specifica (fruttochinasi)."},
{d:"Quale enzima scinde il fruttosio-1-fosfato nel fegato?",o:["L'aldolasi A","L'aldolasi B, che lo scinde in gliceraldeide e diidrossiacetone fosfato","La fruttochinasi","L'esochinasi"],r:1,s:"Nel fegato il fruttosio-1-fosfato viene scisso dall'aldolasi B in gliceraldeide e diidrossiacetone fosfato, che possono entrare nella glicolisi (o essere usati per la sintesi di trigliceridi via glicerolo)."},
{d:"Cos'è la fruttosemia?",o:["Una malattia grave da accumulo di fruttosio-1-fosfato","Un'anomalia metabolica benigna e asintomatica ereditaria dovuta all'assenza della fruttochinasi (1 caso su 13000), che causa aumento del fruttosio ematico","Una mutazione del gene ALDOB","Un deficit di galattochinasi"],r:1,s:"La fruttosemia è un'anomalia metabolica benigna e asintomatica, ereditaria, dovuta all'assenza della fruttochinasi (1 caso su 13000 nascite), che comporta un semplice aumento della concentrazione ematica di fruttosio senza conseguenze gravi."},
{d:"Cosa causa l'intolleranza ereditaria al fruttosio e quali conseguenze ha?",o:["Assenza di fruttochinasi, è benigna","Mutazioni del gene ALDOB (assenza di aldolasi B): porta all'accumulo di fruttosio-1-fosfato che blocca gluconeogenesi e glicogenolisi, causando un rapido calo della glicemia","Eccesso di esochinasi","Deficit di galattosio-1-P uridiltransferasi"],r:1,s:"L'intolleranza ereditaria al fruttosio è una malattia autosomica recessiva (1 caso su 20000-60000) da mutazioni del gene ALDOB (aldolasi B). L'enzima mancante non scinde il fruttosio-1-P, che si accumula bloccando gluconeogenesi e glicogenolisi e provocando ipoglicemia."},
{d:"Quale funzione svolge il fruttosio nel liquido seminale?",o:["È un costituente strutturale degli spermatozoi","È uno dei principali costituenti (2-4 mg/ml), sintetizzato nelle vescicole seminali da glucosio, e viene usato dagli spermatozoi per ricavare energia per il movimento","Inibisce la motilità degli spermatozoi","Serve solo a tamponare il pH"],r:1,s:"Il fruttosio è uno dei più importanti costituenti del liquido seminale (concentrazione 2-4 mg/ml). Si sintetizza nelle vescicole seminali a partire dal glucosio ematico e viene utilizzato dagli spermatozoi per ricavare l'energia utile al movimento."},
{d:"Quale via metabolica collega l'iperglicemia (es. diabete) alla cataratta tramite il sorbitolo?",o:["La glicolisi accelerata","La via dei polioli: l'aldoso reduttasi riduce il glucosio in eccesso a sorbitolo (in cellule come cristallino, nervi, rene, dove l'ingresso di glucosio non dipende da insulina); il sorbitolo accumulato richiama acqua per osmosi","La gluconeogenesi","La fermentazione lattica"],r:1,s:"In iperglicemia (diabete non controllato), in cellule dove l'ingresso di glucosio non è regolato da insulina (cristallino, nervi, rene), molto glucosio entra e viene ridotto a sorbitolo dall'aldoso reduttasi. Il sorbitolo accumulato richiama acqua per osmosi, spiegando alterazioni come la cataratta."},
{d:"Perché l'interconversione galattosio ⇄ glucosio è importante nel neonato e nell'adulto?",o:["Solo per la produzione di energia nel neonato","Nel neonato per convertire il galattosio in glucosio (combustibile); nell'adulto per produrre galattosio da glucosio e sintetizzare lattosio nella ghiandola mammaria e per la sintesi di glicolipidi e glicoproteine","Solo per la sintesi di acidi grassi","Solo per la sintesi di nucleotidi"],r:1,s:"L'interconversione serve nel neonato a convertire il galattosio (dal lattosio materno) in glucosio come combustibile metabolico. Nell'adulto serve a produrre galattosio da glucosio per sintetizzare lattosio nella ghiandola mammaria e per la sintesi di glicolipidi e glicoproteine."},
{d:"Quale enzima fosforila il galattosio nel primo passaggio del suo metabolismo?",o:["L'esochinasi","La galattochinasi, un enzima adattativo stimolato dal galattosio (il lattante ha attività superiore all'adulto), che forma galattosio-1-fosfato","La glucochinasi","La fruttochinasi"],r:1,s:"La galattochinasi fosforila il galattosio a galattosio-1-fosfato (usando ATP e Mg2+). È un enzima adattativo la cui attività è stimolata dal galattosio: il lattante presenta un'attività galattochinasica superiore all'adulto."},
{d:"Quale reazione catalizza la galattosio-1-fosfato uridiltransferasi?",o:["La fosforilazione del galattosio","Lo scambio: galattosio-1-P + UDP-glucosio → glucosio-1-P + UDP-galattosio","L'epimerizzazione dell'UDP-galattosio","La conversione del glucosio-1-P in glucosio-6-P"],r:1,s:"La galattosio-1-fosfato uridiltransferasi catalizza lo scambio tra galattosio-1-P e UDP-glucosio, producendo glucosio-1-P (che entra nella glicolisi via glucosio-6-P) e UDP-galattosio."},
{d:"Quale enzima catalizza l'epimerizzazione reversibile dell'UDP-galattosio in UDP-glucosio?",o:["La galattochinasi","L'UDP-glucosio 4-epimerasi (galattowaldenasi), che usa NAD+ come cofattore passando per l'intermedio UDP-4'-chetoglucosio","La uridiltransferasi","La fosfoglucomutasi"],r:1,s:"L'UDP-glucosio 4-epimerasi (galattowaldenasi) catalizza l'epimerizzazione reversibile dell'UDP-galattosio in UDP-glucosio, usando NAD+ come cofattore e passando per l'intermedio ossidato UDP-4'-chetoglucosio."},
{d:"Quale enzima converte il glucosio-1-fosfato in glucosio-6-fosfato per l'ingresso nella glicolisi?",o:["L'esochinasi","La fosfoglucomutasi","L'uridiltransferasi","La galattochinasi"],r:1,s:"Il glucosio-1-fosfato viene convertito in glucosio-6-fosfato dalla fosfoglucomutasi, permettendo così l'ingresso nella glicolisi."},
{d:"Cosa causa la galattosemia e quali sono le sue manifestazioni cliniche?",o:["Un eccesso di galattochinasi; è asintomatica","Il deficit congenito di galattochinasi e/o di galattosio-1-P uridiltransferasi, che determina accumulo di galattosio nei tessuti e nel sangue, con ritardo mentale, cataratta e danno epatico","Mutazioni del gene ALDOB; causa ipoglicemia","Un deficit di lattasi; causa diarrea"],r:1,s:"La galattosemia è causata dal deficit congenito di galattochinasi e/o di galattosio-1-P uridiltransferasi, che determina l'accumulo di galattosio nei tessuti e nel sangue. Le manifestazioni cliniche includono ritardo mentale, cataratta e danno epatico."},
{d:"Quale enzima sintetizza il lattosio nella ghiandola mammaria e come cambia la sua specificità?",o:["La lattasi, che scinde il lattosio","La galattosiltransferasi: normalmente presente in tutti i tessuti per la sintesi di glicoproteine/glicolipidi, durante la lattazione diventa specifica per il glucosio grazie alla lattoalbumina, deviando verso la sintesi di lattosio","L'uridiltransferasi","La galattochinasi"],r:1,s:"La galattosiltransferasi è presente in tutti i tessuti dove trasferisce galattosio per la sintesi di glicoproteine e glicolipidi. Durante la lattazione, il legame con la lattoalbumina cambia la sua specificità deviandola verso il glucosio, formando lattosio (β-galattosil-(1→4)-glucosio)."},
{d:"Da quale ormone è indotta la lattoalbumina nella ghiandola mammaria?",o:["Dall'insulina","Dalla prolattina, ormone proteico secreto dall'ipofisi anteriore sotto stimolo di PRF e TRH ipotalamici","Dal glucagone","Dagli ormoni tiroidei"],r:1,s:"Nella ghiandola mammaria la lattoalbumina viene indotta dalla prolattina, ormone di natura proteica secreto dall'ipofisi anteriore sotto stimolo di PRF (Prolactin Releasing Factor) e TRH di origine ipotalamica."},
{d:"Quali sono le funzioni tessuto-specifiche della glicolisi in tessuto adiposo e fegato?",o:["Solo produzione di energia","Fonte di glicerolo-3-P per la sintesi dei trigliceridi e fonte di acetil-CoA per la sintesi di acidi grassi","Solo produzione di lattato","Solo sintesi di glicogeno"],r:1,s:"In tessuto adiposo e fegato la glicolisi fornisce glicerolo-3-fosfato per la sintesi dei trigliceridi e acetil-CoA per la sintesi degli acidi grassi. Nell'eritrocita serve esclusivamente per ricavare energia, nel muscolo soprattutto durante sforzo intenso."},
]},
{p:"03_Ormoni_I_parte.pdf",m:2,q:[
{d:"I messaggeri primari trasferiscono l'informazione tra cellule. Quale affermazione li descrive correttamente?",o:["Sono recettori di membrana che riconoscono i secondi messaggeri citoplasmatici","Sono molecole secrete che agiscono su una cellula bersaglio legandone uno specifico recettore","Sono proteine di trasporto plasmatiche che veicolano gli ormoni idrofobici","Sono enzimi intracellulari che amplificano il segnale dopo il legame col recettore"],r:1,s:"I messaggeri primari (ormoni, neurotrasmettitori, segnali paracrini e autocrini) trasferiscono l'informazione da una cellula secernente a una bersaglio mediante interazione con uno specifico recettore. I secondi messaggeri agiscono invece all'interno della cellula."},
{d:"Qual è la differenza tra segnalazione paracrina e autocrina?",o:["La paracrina richiede un potenziale d'azione, l'autocrina no","La paracrina riguarda ormoni steroidei, l'autocrina ormoni peptidici","La paracrina usa il sangue, l'autocrina il liquido interstiziale","La paracrina agisce su cellule vicine, l'autocrina sulla stessa cellula che ha prodotto il segnale"],r:3,s:"Entrambe diffondono nel liquido interstiziale, ma il messaggero paracrino agisce su cellule bersaglio vicine, mentre l'autocrino agisce sulla stessa cellula che lo produce (es. fattori di crescita autoprodotti da cellule tumorali)."},
{d:"Cosa distingue i neurotrasmettitori dagli altri messaggeri chimici?",o:["Diffondono nel liquido interstiziale verso le cellule adiacenti","Si legano sempre a recettori intracellulari modulando la trascrizione","Sono rilasciati dal neurone presinaptico per esocitosi in risposta a un potenziale d'azione","Sono secreti nel sangue e agiscono su cellule molto distanti"],r:2,s:"I neurotrasmettitori sono sintetizzati nel neurone presinaptico e rilasciati per esocitosi in risposta a un potenziale d'azione, agendo a brevissima distanza (ordine dei μm)."},
{d:"Quale caratteristica differenzia gli ormoni da neurotrasmettitori e segnali paracrini?",o:["Sono secreti nel sangue e agiscono anche su cellule bersaglio molto distanti","Non necessitano di un recettore specifico","Agiscono solo sulla cellula che li produce","Sono rilasciati in risposta a un potenziale d'azione"],r:0,s:"Gli ormoni sono sintetizzati da cellule endocrine e secreti nel sangue; a differenza dei segnali a corto raggio, agiscono su cellule bersaglio anche molto distanti (da cm a metri)."},
{d:"A quali concentrazioni operano tipicamente gli ormoni nel sangue?",o:["Concentrazioni molto basse (10^-9 - 10^-12 M)","Concentrazioni molari (1-10 M)","Concentrazioni decimolari (10^-1 M)","Concentrazioni millimolari (10^-3 M)"],r:0,s:"Gli ormoni operano a concentrazioni molto basse (10^-9 - 10^-12 M); proprio per questo il legame con recettori ad alta affinità è essenziale."},
{d:"Perché gli ormoni hanno solitamente un'emivita molto breve?",o:["Perché vengono prodotti in eccesso rispetto al fabbisogno","Perché sono troppo instabili per legare il recettore","Per consentire un controllo puntuale e tempestivo della loro azione","Per accumularsi gradualmente nei tessuti bersaglio"],r:2,s:"L'emivita breve consente di interrompere rapidamente il segnale, permettendo un controllo puntuale dell'azione ormonale ed evitando effetti prolungati."},
{d:"Quale raggruppamento riflette correttamente la classificazione chimica degli ormoni?",o:["Peptidici, derivati da amminoacidi, steroidei ed eicosanoidi","Endocrini, paracrini, autocrini e neurali","Idrofili, idrofobi, anfipatici e ionici","Tropici, sessuali, surrenalici e digestivi"],r:0,s:"In base alla natura chimica gli ormoni si classificano in: proteici/peptidici, derivati da amminoacidi, steroidei e derivati dagli acidi grassi (eicosanoidi)."},
{d:"A quale classe chimica appartengono adrenalina, noradrenalina e ormoni tiroidei?",o:["Ormoni derivati dall'amminoacido tirosina","Eicosanoidi derivati dall'acido arachidonico","Ormoni steroidei derivati dal colesterolo","Ormoni peptidici di sintesi ribosomiale"],r:0,s:"Adrenalina, noradrenalina e ormoni tiroidei derivano tutti dall'amminoacido tirosina."},
{d:"Quali ormoni hanno natura steroidea?",o:["Insulina e glucagone","Corticosurrenalici e ormoni sessuali","Gastrina e secretina","Calcitonina e paratormone"],r:1,s:"Gli ormoni steroidei (derivati dal colesterolo) comprendono i corticosurrenalici, come cortisolo e aldosterone, e gli ormoni sessuali."},
{d:"Come circolano nel sangue gli ormoni idrofilici e dove trovano il recettore?",o:["Dentro vescicole, su recettori mitocondriali","Legati al colesterolo, su recettori citoplasmatici","Legati a proteine di trasporto, su recettori nucleari","In forma libera, su recettori di membrana"],r:3,s:"Gli ormoni proteici e alcuni derivati da amminoacidi sono idrofilici, circolano in forma libera e interagiscono con recettori sulla membrana della cellula bersaglio."},
{d:"Perché gli ormoni steroidei e tiroidei necessitano di proteine di trasporto nel sangue?",o:["Perché devono essere protetti dalle proteasi plasmatiche","Perché la loro natura idrofobica li rende poco solubili nel plasma","Perché devono essere attivati dalle proteine carrier","Perché hanno emivita troppo breve per circolare liberi"],r:1,s:"Gli ormoni steroidei, tiroidei e derivati da acidi grassi sono idrofobici e poco solubili nel plasma, quindi circolano veicolati da specifiche proteine di trasporto; agiscono poi su recettori intracellulari."},
{d:"Quali caratteristiche distinguono la risposta agli ormoni idrofilici da quella agli idrofobici?",o:["Entrambi danno risposta lenta su recettori nucleari","Entrambi danno risposta veloce su recettori di membrana","Idrofilici: risposta veloce e amplificata su recettori di membrana; idrofobici: risposta lenta su recettori intracellulari","Idrofilici: risposta lenta su recettori nucleari; idrofobici: risposta veloce su recettori di membrana"],r:2,s:"Gli ormoni idrofilici agiscono su recettori di membrana con trasduzione del segnale: risposta veloce e amplificata. Gli idrofobici agiscono su recettori citoplasmatici/nucleari modulando la trascrizione: risposta lenta."},
{d:"Nel recettore accoppiato a proteine G, quale sequenza descrive la trasmissione del segnale?",o:["Il ligando spiazza le proteine Hsp e lega il recettore al DNA","Il ligando autofosforila il recettore attivandone l'attività chinasica","Il ligando entra nella cellula e attiva direttamente un fattore di trascrizione","Il ligando attiva una proteina G legante GTP che regola un enzima generatore di secondo messaggero"],r:3,s:"Nel recettore accoppiato a proteine G il legame del ligando attiva una proteina G che lega GTP; questa regola un enzima (es. adenilato ciclasi) che genera un secondo messaggero intracellulare."},
{d:"Come si attiva un recettore enzimatico ad attività tirosin-chinasica?",o:["Mediante autofosforilazione su residui di tirosina innescata dal legame del ligando","Mediante spiazzamento delle proteine Hsp dal dominio catalitico","Mediante idrolisi del cAMP a opera della fosfodiesterasi","Mediante legame al GTP da parte della subunità intracellulare"],r:0,s:"Il legame del ligando a un recettore tirosin-chinasico ne innesca l'attività enzimatica mediante autofosforilazione; la chinasi può poi attivare fattori di trascrizione e modificare l'espressione genica."},
{d:"In assenza dell'ormone, a cosa sono associati i recettori citoplasmatici degli ormoni idrofobici?",o:["Al GTP, che ne blocca il dominio catalitico","Alla membrana plasmatica, tramite un'ancora lipidica","Al cAMP, che ne mantiene la conformazione inattiva","A proteine Hsp, che bloccano la regione di legame al DNA"],r:3,s:"I recettori citoplasmatici sono legati a proteine Hsp che mascherano la regione di interazione col DNA; l'ormone spiazza le Hsp permettendo il legame al DNA e l'innesco della trascrizione."},
{d:"Quali ormoni usano recettori nucleari già associati alla cromatina?",o:["Al cAMP, che ne stabilizza la conformazione attiva","Al GTP, che ne maschera il dominio di legame al DNA","A proteine Hsp, che bloccano la regione di legame al DNA","Alla membrana plasmatica tramite un'ancora glicolipidica"],r:2,s:"I recettori nucleari sono utilizzati da ormoni sessuali, tiroidei e derivati dalla vitamina D; i corticosteroidi usano invece recettori citoplasmatici."},
{d:"Quali sono i tre principali meccanismi d'azione degli ormoni sulla cellula bersaglio?",o:["Azione sulla permeabilità di membrana, sull'attività enzimatica e sull'espressione genica","Glicosilazione, fosforilazione e ubiquitinazione del ligando","Endocitosi, esocitosi e trasporto vescicolare","Sintesi del recettore, sua degradazione e suo riciclo"],r:0,s:"Gli ormoni agiscono modificando la permeabilità di membrana (es. GLUT4), modulando l'attività di enzimi (cascate chinasiche/secondi messaggeri) e regolando l'espressione genica."},
{d:"Quale esempio illustra l'azione di un ormone sulla permeabilità di membrana?",o:["Glucagone che attiva l'adenilato ciclasi e la PKA","Calcitonina che aumenta i livelli intracellulari di cAMP","Cortisolo che modula la trascrizione di geni bersaglio","Insulina che induce la traslocazione di GLUT4 in muscolo e adipocita"],r:3,s:"L'insulina stimola l'ingresso di glucosio inducendo la traslocazione del trasportatore GLUT4 sulla membrana di muscolo e adipocita: un classico esempio di azione sulla permeabilità."},
{d:"Cos'è il CREB nell'azione ormonale sull'espressione genica?",o:["Una proteina G stimolatoria accoppiata al recettore","Un secondo messaggero generato dall'adenilato ciclasi","Un fattore (CRE-binding protein) che, fosforilato, attiva la trascrizione","Un canale ionico attivato dal cAMP"],r:2,s:"Il CREB (CRE-binding protein) è un co-regolatore trascrizionale: fosforilato dalla PKA, attiva la trascrizione di geni legandosi all'elemento CRE."},
{d:"Quale struttura rappresenta il centro di comando su cui agiscono i segnali nervosi del sistema endocrino?",o:["L'ipofisi posteriore, che immagazzina i fattori di rilascio","L'ipotalamo, che produce i fattori di rilascio per l'ipofisi","La corteccia surrenale, che integra gli stimoli nervosi","La ghiandola pineale, che coordina il ritmo ormonale"],r:1,s:"I segnali nervosi convergono sull'ipotalamo, il centro di comando che produce i fattori di rilascio diretti all'ipofisi."},
{d:"Cosa stimolano i fattori di rilascio prodotti dall'ipotalamo?",o:["Direttamente la tiroide a produrre tiroxina","L'ipofisi posteriore (ossitocina/vasopressina) e l'anteriore (ormoni tropici)","Le paratiroidi a secernere paratormone","Il pancreas a secernere insulina e glucagone"],r:1,s:"I fattori di rilascio ipotalamici stimolano l'ipofisi posteriore a secernere ossitocina e vasopressina e l'ipofisi anteriore a produrre gli ormoni tropici."},
{d:"Quali ghiandole NON dipendono dall'asse ipotalamo-ipofisario ma rispondono ad altri stimoli?",o:["La tiroide (stimolo nervoso) e le gonadi (stimolo chimico)","L'ipofisi anteriore e l'ipofisi posteriore","La corteccia surrenale (ACTH) e la tiroide (TSH)","La midollare del surrene (stimolo nervoso non ipotalamico) e il pancreas (glicemia)"],r:3,s:"La midollare del surrene risponde a stimolo nervoso non ipotalamico (adrenalina) e il pancreas a stimolo chimico, la glicemia (insulina/glucagone), al di fuori del controllo ipotalamo-ipofisario."},
{d:"Qual è la corretta sequenza dell'asse dello stress che porta al rilascio di cortisolo?",o:["Ipotalamo (CRH) → ipofisi anteriore (ACTH) → corteccia surrenale (cortisolo)","Ipotalamo (ACTH) → ipofisi (CRH) → midollare (adrenalina)","Surrene (cortisolo) → ipofisi (ACTH) → ipotalamo (CRH)","Ipofisi (ACTH) → ipotalamo (CRH) → surrene (cortisolo)"],r:0,s:"Lo stress stimola l'ipotalamo a rilasciare CRH, che induce l'ipofisi anteriore a rilasciare ACTH, che a sua volta stimola la corteccia surrenale a produrre cortisolo."},
{d:"Cosa significa che ad ogni tappa dell'asse ormonale il segnale viene amplificato?",o:["Che il segnale si attenua progressivamente lungo la cascata","Che ogni ghiandola produce lo stesso ormone in serie","Che l'emivita degli ormoni raddoppia ad ogni passaggio","Che quantità minime di fattore di rilascio generano quantità molto maggiori di ormone finale"],r:3,s:"L'amplificazione fa sì che pochi ng di fattore di rilascio producano mg di ormone finale (CRH in ng → ACTH in μg → cortisolo in mg)."},
{d:"Come opera il feedback negativo nell'asse ormonale?",o:["L'ormone finale aumenta la propria stessa sintesi","L'ormone finale stimola la produzione delle tappe precedenti","L'ormone finale in eccesso inibisce il rilascio degli ormoni delle tappe precedenti","L'ormone finale viene degradato dalle ghiandole a monte"],r:2,s:"Nel feedback negativo un ormone finale (o un intermedio) in eccesso inibisce le tappe precedenti, garantendo l'omeostasi metabolica."},
{d:"Come si definisce l'omeostasi metabolica?",o:["La capacità di mantenere costanti metaboliti e parametri biochimici nonostante variazioni esterne","Il bilancio tra sintesi e degradazione del solo glicogeno","L'aumento progressivo dei metaboliti durante il digiuno","L'eliminazione renale degli ormoni in eccesso"],r:0,s:"L'omeostasi metabolica è la capacità dell'organismo di mantenere costanti metaboliti (glucosio, corpi chetonici, ATP) e parametri (pH) nonostante variazioni di apporto alimentare, dispendio energetico o stato fisiologico."},
{d:"Cosa caratterizza un meccanismo a feedback negativo?",o:["Aumenta sempre la velocità del processo regolato","È attivo esclusivamente durante il parto","La risposta si oppone alla variazione, riportando il parametro al valore fisiologico","Amplifica indefinitamente lo stimolo iniziale"],r:2,s:"Nel feedback negativo la risposta si oppone alla variazione iniziale riportando il parametro verso il valore fisiologico (es. termoregolazione con centro nell'ipotalamo)."},
{d:"Cosa caratterizza un meccanismo a feedback positivo?",o:["Mantiene costante un parametro fisiologico","Riduce progressivamente l'intensità dello stimolo","Riporta il parametro al valore di partenza","Accelera o intensifica un processo in risposta allo stimolo"],r:3,s:"Il feedback positivo accelera/intensifica un processo in seguito allo stimolo ricevuto; un esempio è il rilascio di ossitocina durante il parto."},
{d:"Qual è il range fisiologico costante della glicemia?",o:["5-10 mg/dL","70-130 mg/dL","20-40 mg/dL","200-300 mg/dL"],r:1,s:"L'omeostasi del glucosio mantiene la glicemia in un range di circa 70-130 mg/dL, regolata dall'equilibrio tra uptake, immagazzinamento e rilascio del glucosio."},
{d:"Perché il tessuto nervoso necessita di un continuo apporto di glucosio?",o:["Perché possiede troppi mitocondri da rifornire","Perché è privo degli enzimi della beta-ossidazione","Perché produce insulina che consuma glucosio","Perché converte il glucosio in corpi chetonici"],r:1,s:"Il tessuto nervoso è carente di tutti gli enzimi della beta-ossidazione, quindi dipende dal glucosio (circa 120 g/die, 35-50% del consumo totale)."},
{d:"Perché i globuli rossi dipendono dalla glicolisi anaerobia per l'ATP?",o:["Perché utilizzano prevalentemente corpi chetonici","Perché possiedono molti mitocondri molto attivi","Perché producono insulina che blocca la fosforilazione ossidativa","Perché sono privi di mitocondri"],r:3,s:"Gli eritrociti, privi di mitocondri, ricavano ATP solo dalla glicolisi anaerobia (circa 35 g/die di glucosio, 12-15% del consumo totale)."},
{d:"Quale coppia di ormoni ad azione opposta garantisce l'omeostasi glicemica?",o:["Cortisolo (ipoglicemizzante) e adrenalina (iperglicemizzante)","Tiroxina (ipoglicemizzante) e GH (iperglicemizzante)","Calcitonina (iperglicemizzante) e paratormone (ipoglicemizzante)","Insulina (ipoglicemizzante) e glucagone (iperglicemizzante)"],r:3,s:"L'omeostasi glicemica è garantita dall'insulina, unico ormone ipoglicemizzante, e dal glucagone, ad azione opposta iperglicemizzante."},
{d:"Qual è la differenza tra porzione esocrina ed endocrina del pancreas?",o:["L'esocrina produce insulina, l'endocrina enzimi digestivi","L'esocrina produce il succo pancreatico, l'endocrina insulina e glucagone","Entrambe producono ormoni ma in tessuti diversi","L'esocrina produce glucagone, l'endocrina succo gastrico"],r:1,s:"La porzione esocrina produce il succo pancreatico con enzimi digestivi; la porzione endocrina (isole di Langerhans) produce insulina e glucagone."},
{d:"Quali cellule delle isole di Langerhans producono rispettivamente insulina, glucagone e somatostatina?",o:["Cellule α, cellule β e cellule γ","Cellule acinari, parietali e principali","Cellule β, cellule α e cellule δ","Cellule δ, cellule γ e cellule β"],r:2,s:"Nelle isole di Langerhans le cellule β producono insulina, le cellule α glucagone e le cellule δ somatostatina."},
{d:"Quali sono i tessuti bersaglio dell'insulina?",o:["Fegato, muscolo e tessuto adiposo","Rene, osso e intestino","Solo il sistema nervoso centrale","Cute, milza e polmone"],r:0,s:"I tessuti bersaglio dell'insulina sono fegato, muscolo e tessuto adiposo; il glucagone agisce su fegato e tessuto adiposo."},
{d:"Com'è strutturata l'insulina matura?",o:["Catena A (21 aa) e catena B (30 aa) unite da ponti disolfuro","Due catene identiche unite da legami idrogeno","Tre catene corte unite da ponti salini","Una singola catena di 51 amminoacidi ripiegata su sé stessa"],r:0,s:"L'insulina matura è formata da una catena A (21 aa) e una catena B (30 aa) unite da due ponti S-S intercatena (oltre a legami idrogeno e ponti salini); la catena A ha anche un ponte S-S intracatena."},
{d:"Cosa conferisce all'insulina la sua struttura particolarmente compatta?",o:["L'elevato contenuto di residui idrofobici esposti","La presenza di un solo ponte disolfuro centrale","Le numerose interazioni saline e legami idrogeno oltre ai ponti disolfuro","Il legame stabile con lo zinco intracellulare"],r:2,s:"La compattezza dell'insulina deriva dalle numerose interazioni saline e legami idrogeno che, insieme ai ponti disolfuro, tengono coese le catene A e B."},
{d:"Quali sono i precursori dell'insulina e la loro dimensione?",o:["Pre-proinsulina (104 aa) e proinsulina (81 aa)","Macroinsulina (160 aa) e mini-insulina (21 aa)","Solo proinsulina (51 aa)","Pre-insulina (30 aa) e insulina (21 aa)"],r:0,s:"L'insulina è sintetizzata come pre-proinsulina (104 aa), poi proinsulina (81 aa); la proteolisi nel Golgi rimuove il peptide C generando l'ormone maturo."},
{d:"Perché il peptide C è un buon indicatore della secrezione di insulina?",o:["Perché ha emivita più lunga ed è prodotto in quantità equimolari all'insulina","Perché è più attivo biologicamente dell'insulina","Perché si lega ai recettori insulinici epatici","Perché viene secreto solo durante l'ipoglicemia"],r:0,s:"Il peptide C, prodotto in quantità equimolari all'insulina e con emivita plasmatica più lunga, è un ottimo marcatore della secrezione insulinica, utile nella diagnosi del diabete giovanile."},
{d:"Dove è localizzato il gene che codifica per l'insulina?",o:["Nel DNA mitocondriale","Nel braccio corto del cromosoma 11","Sul cromosoma 21","Sul cromosoma X"],r:1,s:"Il gene dell'insulina è localizzato nel braccio corto del cromosoma 11."},
{d:"Quale ione è indispensabile per la fusione delle vescicole e il rilascio di insulina?",o:["Magnesio (Mg2+)","Calcio (Ca2+)","Sodio (Na+)","Cloro (Cl-)"],r:1,s:"L'aumento citoplasmatico di Ca2+ è necessario per la fusione delle vescicole con la membrana e quindi per il rilascio di insulina in condizioni di alta glicemia."},
{d:"Quale ione stabilizza le strutture esameriche dell'insulina in soluzione?",o:["Rame","Zinco","Ferro","Calcio"],r:1,s:"In soluzione l'insulina tende ad aggregare in esameri stabilizzati dallo zinco."},
{d:"Quale sequenza descrive correttamente il rilascio di insulina dalla cellula β stimolato dal glucosio?",o:["L'insulina entra nella cellula β e depolarizza la membrana aprendo i canali K+","Il glucosio inibisce la glicolisi riducendo l'ATP e chiudendo i canali Ca2+","Glucosio via GLUT2 → ATP → chiusura canali K+ → depolarizzazione → ingresso Ca2+ → esocitosi","Glucosio entra via GLUT4, l'ATP apre i canali K+ e il Ca2+ esce dalla cellula"],r:2,s:"Il glucosio entra via GLUT2, viene metabolizzato aumentando l'ATP; questo chiude i canali K+ ATP-dipendenti causando depolarizzazione, che apre i canali Ca2+ voltaggio-dipendenti; l'ingresso di Ca2+ scatena l'esocitosi dei granuli."},
{d:"Come viene descritta la risposta secretoria di insulina alla stimolazione da glucosio?",o:["Ritardata, assente nella prima ora dopo lo stimolo glucidico","Monofasica, con un singolo picco progressivo e prolungato","Trifasica, con tre picchi successivi di ampiezza crescente","Bifasica: fase precoce (insulina preformata) e tardiva (di nuova sintesi)"],r:3,s:"La risposta è bifasica: early phase (insulina depositata/preformata) e late phase (insulina di nuova sintesi)."},
{d:"Qual è la vita media dell'insulina circolante e dove viene inattivata?",o:["7-15 minuti, inattivata nei tessuti bersaglio (insulinasi, trans-deidrogenasi)","Circa 24 ore, inattivata esclusivamente a livello dei reni","Pochi secondi, demolita al primo passaggio attraverso i polmoni","Circa 48 ore, degradata molto lentamente nel plasma circolante"],r:0,s:"L'insulina circolante ha vita media di 7-15 minuti; è inattivata nei tessuti bersaglio: il fegato possiede l'insulina trans-deidrogenasi e proteasi lisosomiali (insulinasi)."},
{d:"Quanta insulina viene mediamente secreta al giorno?",o:["Circa 0,001 unità per Kg di peso corporeo","Circa 1 unità per Kg di peso corporeo","Una quantità non quantificabile","Circa 100 unità per Kg di peso corporeo"],r:1,s:"La secrezione giornaliera di insulina è circa 1 unità/Kg di peso corporeo."},
{d:"Qual è la struttura del recettore dell'insulina?",o:["Un recettore citoplasmatico associato a proteine Hsp","Una glicoproteina dimerica con subunità α (legame ormone) e β (tirosin-chinasi)","Un canale ionico ligando-dipendente","Un recettore monomerico accoppiato a proteine G"],r:1,s:"Il recettore insulinico è una glicoproteina transmembrana dimerica: le subunità α extracellulari legano l'ormone, le subunità β intracellulari hanno attività tirosin-chinasica."},
{d:"Cosa accade al recettore dell'insulina dopo il legame con l'ormone?",o:["Si dimerizza, si autofosforila e fosforila la proteina IRS avviando la cascata","Lega il GTP e attiva una proteina G","Viene internalizzato e immediatamente degradato","Entra nel nucleo trasportando l'ormone"],r:0,s:"Il legame dell'insulina provoca dimerizzazione e autofosforilazione del recettore, che fosforila la proteina IRS (Insulin Receptor Substrate) avviando la cascata di segnalazione."},
{d:"Quali sono le due grandi categorie di effetti del segnale insulinico?",o:["Effetti pro-coagulanti ed effetti vasodilatatori","Effetti eccitatori ed effetti inibitori sui neuroni","Effetti metabolici ed effetti sull'espressione genica","Effetti sul trasporto ionico ed effetti osmotici"],r:2,s:"Il segnale insulinico produce effetti metabolici (attività enzimatica, permeabilità di membrana) ed effetti di regolazione dell'espressione genica."},
{d:"Perché l'insulina è considerata un ormone anabolico?",o:["Perché stimola la sintesi di glicogeno, lipidi e proteine e la captazione di nutrienti","Perché aumenta la glicemia mobilitando le riserve energetiche dei tessuti","Perché attiva la lipolisi e la beta-ossidazione nel tessuto adiposo","Perché favorisce la degradazione di glicogeno, lipidi e proteine"],r:0,s:"L'insulina stimola la fase sintetica del metabolismo: promuove l'assunzione di glucosio e amminoacidi e la sintesi di glicogeno, acidi grassi/trigliceridi e proteine."},
{d:"Quali sono gli effetti dell'insulina sul metabolismo glucidico?",o:["Nessun effetto netto sul metabolismo del glucosio","+ glicolisi e + glicogenosintesi; - glicogenolisi e - gluconeogenesi","- glicolisi e - glicogenosintesi; + gluconeogenesi","+ glicogenolisi e + gluconeogenesi"],r:1,s:"L'insulina stimola glicolisi e glicogenosintesi e inibisce glicogenolisi e gluconeogenesi."},
{d:"Quali sono gli effetti dell'insulina sul metabolismo lipidico?",o:["+ sintesi di acidi grassi e trigliceridi; - ossidazione degli acidi grassi","Solo aumento della beta-ossidazione mitocondriale","- sintesi di trigliceridi e + lipolisi","+ ossidazione e - sintesi degli acidi grassi"],r:0,s:"L'insulina stimola la sintesi di acidi grassi e trigliceridi e inibisce la loro ossidazione."},
{d:"Tramite quali tre meccanismi l'insulina esercita i suoi effetti intracellulari?",o:["Inducendo la degradazione di glucochinasi e glicogenosintasi nel proteasoma","Attivando solo il trasporto vescicolare e l'esocitosi degli enzimi epatici","Modulando esclusivamente la trascrizione dei geni del metabolismo lipidico","Su permeabilità (GLUT4), attività enzimatica (glicogenosintasi) ed espressione genica (glucochinasi)"],r:3,s:"L'insulina modifica la permeabilità (GLUT4), modula l'attività di enzimi (es. glicogenosintasi) e induce/reprime la sintesi di proteine (es. glucochinasi)."},
{d:"Con quale meccanismo l'insulina favorisce l'ingresso di glucosio in muscolo e adipocita?",o:["Inducendo la sintesi di glucochinasi","Inibendo il trasportatore GLUT2","Attivando l'esochinasi mitocondriale","Promuovendo l'inserimento dei trasportatori GLUT4 in membrana"],r:3,s:"Nel muscolo e nell'adipocita l'insulina induce la traslocazione di GLUT4 sulla membrana, consentendo l'ingresso del glucosio."},
{d:"Come agisce l'insulina sull'utilizzo del glucosio nell'epatocita?",o:["Inibisce la glicolisi favorendo la gluconeogenesi","Inserisce GLUT4 sulla membrana epatica","Blocca il trasportatore GLUT2 costitutivo","Induce la glucochinasi, mantenendo basso il glucosio libero intracellulare"],r:3,s:"Nel fegato (GLUT2 costitutivo) l'insulina induce la glucochinasi; convertendo il glucosio in G-6-P si mantiene basso il glucosio libero, favorendone l'ingresso."},
{d:"Su quali geni epatici agisce l'insulina a livello trascrizionale?",o:["Induce G6P fosfatasi e PEPCK","Non influenza la trascrizione dei geni metabolici","Induce la glucochinasi e reprime G6P fosfatasi e PEPCK","Reprime sia la glucochinasi sia la PEPCK"],r:2,s:"Nel fegato l'insulina induce il gene della glucochinasi e reprime quelli di glucosio-6-fosfatasi e PEPCK (enzimi gluconeogenici)."},
{d:"Qual è il destino del fattore FOXO1 in risposta all'insulina?",o:["Viene attivato e stimola la gluconeogenesi","Viene fosforilato dalla PKB e degradato, inibendo i geni gluconeogenici","Viene trasportato nel nucleo per attivare la glicolisi","Viene defosforilato e lega il promotore della PEPCK"],r:1,s:"FOXO1 viene fosforilato dalla PKB su segnale insulinico e poi degradato, inibendo l'espressione di geni gluconeogenici come PEPCK e glucosio-6-fosfatasi."},
{d:"Perché nel fegato la PFK-1 resta attiva anche con elevate concentrazioni di ATP?",o:["Grazie al fruttosio 2,6-bisfosfato, attivatore efficace a concentrazioni molto basse","Perché il citrato ne aumenta l'affinità per il substrato","Perché l'AMP è assente nell'epatocita","Perché l'ATP funge da attivatore allosterico"],r:0,s:"Nel fegato il fruttosio 2,6-bisfosfato attiva la PFK-1 a concentrazioni anche 10 volte inferiori rispetto agli altri modulatori (ATP, AMP, citrato), mantenendola attiva."},
{d:"Come regola l'insulina la sintesi di fruttosio 2,6-bisfosfato nel fegato?",o:["Attiva la FBPasi-2 degradando il F2,6BP","Blocca la conversione di fruttosio 6-fosfato","Mantiene attiva (defosforilata) la PFK-2 che sintetizza F2,6BP","Inibisce la PFK-2 riducendone il prodotto"],r:2,s:"L'insulina, via defosforilazione, mantiene attiva la PFK-2 che sintetizza fruttosio 2,6-bisfosfato, regolatore chiave che coordina glicolisi e gluconeogenesi."},
{d:"Quale effetto ha il fruttosio 2,6-bisfosfato sulle vie del glucosio?",o:["Non esercita alcun effetto allosterico sugli enzimi delle due vie","Inibisce la glicolisi attivando la FBPasi-1 e stimola la gluconeogenesi","Attiva contemporaneamente sia la PFK-1 sia la FBPasi-1 epatiche","Stimola la glicolisi attivando la PFK-1 e inibisce la gluconeogenesi (inibisce FBPasi-1)"],r:3,s:"Il fruttosio 2,6-bisfosfato stimola la glicolisi attivando la PFK-1 e inibisce la gluconeogenesi inibendo la FBPasi-1."},
{d:"Come è regolata la piruvato chinasi (PK) epatica e cosa fa l'insulina?",o:["Per fosforilazione/defosforilazione: l'insulina la defosforila attivandola","L'insulina la fosforila inattivandola","Il glucagone la defosforila per attivarla","È costitutivamente attiva, indipendente dagli ormoni"],r:0,s:"La PK epatica è regolata per fosforilazione/defosforilazione: in bassa glicemia è fosforilata e inattiva (PEP usato per gluconeogenesi); con alta glicemia e insulina viene defosforilata e attivata."},
{d:"Come l'insulina mantiene attiva la glicogeno sintasi (GS)?",o:["Promuovendo la degradazione della GS nel proteasoma dipendente da ubiquitina","Attivando la GSK3, che fosforila la glicogeno sintasi rendendola attiva","Fosforilando direttamente la GS sui residui di serina e attivandola","Inattivando la GSK3 e attivando la fosfatasi, mantenendo la GS defosforilata e attiva"],r:3,s:"L'insulina inattiva la GSK3 (per fosforilazione via PKB) e attiva la fosfoproteina fosfatasi; di conseguenza la glicogeno sintasi rimane defosforilata e attiva, promuovendo la glicogenosintesi."},
{d:"In quali isoforme interconvertibili esiste la glicogeno fosforilasi?",o:["Fosforilasi A (inattiva) e fosforilasi B (sempre attiva)","Isoforma alfa e beta funzionalmente identiche","Fosforilasi A (attiva, fosforilata) e fosforilasi B (meno attiva, defosforilata)","Una sola forma costitutivamente attiva"],r:2,s:"La glicogeno fosforilasi esiste come fosforilasi A (attiva, fosforilata) e fosforilasi B (meno attiva, defosforilata)."},
{d:"Come agisce il glucosio sulla glicogeno fosforilasi epatica?",o:["Da attivatore allosterico che ne stimola la glicogenolisi","Da modulatore allosterico negativo, favorendo la defosforilazione (inattivazione)","Non interagisce con l'enzima","Da substrato che ne aumenta la velocità catalitica"],r:1,s:"Nel fegato il glucosio è modulatore allosterico negativo: legandosi alla fosforilasi A espone i residui di Ser fosforilati alla fosfatasi (stimolata dall'insulina), convertendola nella forma B inattiva e inibendo la glicogenolisi."},
{d:"Quali sono gli effetti anabolici dell'insulina sul metabolismo lipidico?",o:["Solo inibizione della sintesi di acidi grassi","+ lipolisi, + beta-ossidazione e + chetogenesi","- sintesi di colesterolo e + mobilizzazione dei trigliceridi","+ lipogenesi e sintesi di trigliceridi/colesterolo; - lipolisi e - beta-ossidazione"],r:3,s:"L'insulina stimola lipogenesi e sintesi di trigliceridi e colesterolo, e inibisce lipolisi, trasporto carnitina-dipendente e beta-ossidazione."},
{d:"Tramite quali enzimi chiave l'insulina indirizza i carboidrati verso i triacilgliceroli?",o:["Attivando la lipasi ormone-sensibile e la CPT-1","Attivando piruvato deidrogenasi (acetil-CoA) e acetil-CoA carbossilasi (malonil-CoA)","Inibendo piruvato deidrogenasi e acetil-CoA carbossilasi","Inducendo solo la HMG-CoA reduttasi"],r:1,s:"L'insulina defosforila e attiva la piruvato deidrogenasi (acetil-CoA mitocondriale) e attiva l'acetil-CoA carbossilasi (malonil-CoA citosolico), avviando la sintesi degli acidi grassi."},
{d:"Come è regolata la piruvato deidrogenasi (PDH) e qual è l'effetto dell'insulina?",o:["Per fosforilazione/defosforilazione: l'insulina la attiva per defosforilazione","L'insulina la fosforila inattivandola","È sempre inattiva, indipendentemente dagli ormoni","Solo il glucagone può attivarla per defosforilazione"],r:0,s:"La PDH è regolata per fosforilazione/defosforilazione: in bassa glicemia è fosforilata e inattiva; l'insulina (via fosfatasi) la defosforila e attiva, mentre il glucagone (via chinasi) la mantiene inattiva."},
{d:"Perché in presenza di insulina si accumula citrato che esce nel citosol?",o:["Perché il citrato non può attraversare la membrana mitocondriale","Perché l'alta carica energetica inibisce l'isocitrico deidrogenasi, accumulando citrato per la lipogenesi","Perché il glucagone blocca completamente il ciclo di Krebs","Perché la PDH risulta inattiva e manca acetil-CoA"],r:1,s:"L'elevata carica energetica inibisce l'isocitrico deidrogenasi: l'acetil-CoA si accumula come citrato che esce nel citosol fornendo acetil-CoA per la sintesi degli acidi grassi."},
{d:"Come è regolata l'acetil-CoA carbossilasi (ACC), enzima chiave della lipogenesi?",o:["Solo a livello trascrizionale, per induzione genica da parte del glucosio","Solo da modulatori allosterici, senza alcuna regolazione per fosforilazione","Allostericamente (+citrato, -palmitoil-CoA) e per fosforilazione (attiva se defosforilata)","In modo costitutivo, restando sempre attiva indipendentemente dagli ormoni"],r:2,s:"L'ACC è attivata dal citrato e inibita dal palmitoil-CoA (allosterici) ed è regolata per fosforilazione: defosforilata (insulina) è attiva, fosforilata (glucagone, via AMPK) è inattiva per dissociazione dei protomeri."},
{d:"Quale insieme di effetti riassume il ruolo dell'insulina nella lipogenesi?",o:["Attivazione di PDH, citrato liasi, ACC e HMG-CoA reduttasi; inibizione della CPT-1","Inibizione di tutti gli enzimi lipogenici e attivazione della CPT-1","Solo attivazione della beta-ossidazione mitocondriale","Inibizione della citrato liasi e dell'enzima malico"],r:0,s:"In alta glicemia l'insulina attiva piruvato deidrogenasi, citrato liasi, ACC e HMG-CoA reduttasi e induce citrato liasi, enzima malico e acido grasso sintetasi; inibisce la carnitina acil-transferasi I (CPT-1) limitando la beta-ossidazione."},
{d:"Come si realizza l'effetto antilipolitico dell'insulina?",o:["Bloccando la fosfodiesterasi e la PP1","Inibendo la lipasi ormone-sensibile via fosfodiesterasi (riduce cAMP) e PP1","Stimolando direttamente la mobilizzazione dei trigliceridi","Attivando la lipasi ormone-sensibile e aumentando il cAMP"],r:1,s:"L'insulina inibisce la lipasi ormone-sensibile attivando la fosfodiesterasi (riduce il cAMP) e la PP1 (la defosforila); attiva inoltre la lipoproteina-lipasi. Questo effetto si realizza a concentrazioni di insulina più basse di altri."},
{d:"Con quali meccanismi l'insulina stimola l'incorporazione di amminoacidi nelle proteine?",o:["Attivando il trasporto di amminoacidi e la sintesi proteica ribosomiale","Bloccando l'ingresso di amminoacidi nelle cellule","Degradando le proteine preesistenti per liberare amminoacidi","Inibendo i ribosomi per risparmiare energia"],r:0,s:"L'insulina, tipico ormone anabolico, attiva il trasporto intracellulare degli amminoacidi e la sintesi proteica a livello ribosomiale."},
{d:"Come si definisce il diabete mellito?",o:["Una carenza isolata di glucagone con ridotta produzione epatica di glucosio","Un'unica malattia ereditaria a trasmissione monogenica autosomica","Un eccesso cronico di secrezione di insulina con ipoglicemia ricorrente","Sindromi da insufficiente produzione o azione dell'insulina, con iperglicemia"],r:3,s:"Il diabete è un gruppo eterogeneo di sindromi dovute a insufficiente produzione di insulina o a sua inefficiente azione sulle cellule bersaglio; il segno principale è l'iperglicemia (>160-180 mg/dL) con glicosuria."},
{d:"Cos'è la glicosuria nel contesto del diabete?",o:["Una condizione di ipoglicemia persistente","L'accumulo eccessivo di glicogeno epatico","Il deposito di glucosio nei tessuti periferici","L'escrezione renale di glucosio quando supera la soglia di riassorbimento"],r:3,s:"La glicosuria è l'escrezione urinaria di glucosio che compare quando la glicemia supera la soglia renale (>160-180 mg/dL) e il rene non riesce a riassorbirlo tutto."},
{d:"Quali sono le principali categorie di diabete?",o:["Diabete di classe A, di classe B e di classe C in base alla gravità","Solo diabete di tipo 1 e diabete di tipo 2 dell'adulto","Tipo 1, tipo 2, gestazionale, monogenico (MODY) e secondario a patologie/farmaci","Solo diabete gestazionale e diabete secondario all'uso di cortisone"],r:2,s:"Le categorie comprendono: tipo 1 (insulino-dipendente), tipo 2 (insulino-indipendente), gestazionale, monogenico (es. MODY) e secondario ad altra patologia o farmaci."},
{d:"Quali conseguenze metaboliche derivano dalla mancata azione dell'insulina?",o:["Aumento della sintesi di glicogeno e trigliceridi","Riduzione dell'ossidazione degli acidi grassi","Iperglicemia, aumento di lipolisi e corpi chetonici, fino ad acidosi e coma","Ipoglicemia con riduzione dei corpi chetonici"],r:2,s:"Senza azione insulinica si ha iperglicemia (glucosio non utilizzato), aumento di lipolisi e ossidazione degli acidi grassi con accumulo di corpi chetonici, alterazioni acido-base/idrosaline e acidosi diabetica fino al coma."},
{d:"Qual è la causa del diabete di tipo 1?",o:["Distruzione autoimmune delle cellule β, con insulina assente","Azione degli ormoni della gravidanza","Eccesso di produzione di insulina","Insulino-resistenza dei tessuti periferici"],r:0,s:"Il diabete di tipo 1 deriva dalla distruzione autoimmune delle cellule β (spesso post-infettiva in soggetti predisposti): insulina assente, insorgenza giovanile rapida, magrezza, chetoacidosi, prognosi permanente."},
{d:"Cosa caratterizza il diabete di tipo 2?",o:["Insulina presente (anche ridotta) ma tessuti non responsivi (insulino-resistenza)","Insorgenza esclusivamente in gravidanza con remissione dopo il parto","Decorso acuto e reversibile con rapida insorgenza e magrezza marcata","Assenza totale di insulina dovuta a distruzione autoimmune delle cellule β"],r:0,s:"Nel diabete di tipo 2 l'insulina è presente (anche se ridotta) ma i tessuti bersaglio non rispondono (insulino-resistenza); tipico dell'adulto, lenta progressione, sovrappeso, complicanze cardiovascolari, decorso cronico."},
{d:"Quali fattori possono favorire l'insulino-resistenza?",o:["Bassi livelli di cortisolo e di ormoni sessuali circolanti","Eccesso di trasportatori GLUT4 esposti sulla membrana cellulare","Alti livelli di cortisolo/ormoni sessuali e difetti post-recettoriali (fosforilazioni Ser/Thr)","Aumentata sintesi e secrezione compensatoria di insulina dal pancreas"],r:2,s:"L'insulino-resistenza può essere favorita da alti livelli di cortisolo e ormoni sessuali e da difetti post-recettoriali dovuti a fosforilazioni in Ser/Thr dei recettori, che ne riducono la capacità di segnalazione."},
{d:"Cosa caratterizza il diabete gestazionale?",o:["Decorso cronico e permanente nell'adulto","Insulina assente per distruzione autoimmune delle cellule β","Macrosomia materna con iperglicemia neonatale","Insulina presente ma insufficiente per gli ormoni della gravidanza, spesso reversibile"],r:3,s:"Il diabete gestazionale ha insulina presente ma insufficiente, dovuta agli ormoni della gravidanza; spesso asintomatico con macrosomia fetale, può dare ipoglicemia neonatale ed è spesso reversibile."},
{d:"Quali sono le caratteristiche del glucagone?",o:["Ormone peptidico ipoglicemizzante derivato dalla tirosina","Ormone steroideo ipoglicemizzante di 84 aa","Ormone eicosanoide a rapida emivita","Ormone polipeptidico iperglicemizzante di 29 aa, da un precursore di 160 aa"],r:3,s:"Il glucagone è un ormone polipeptidico iperglicemizzante di 29 amminoacidi, sintetizzato da un precursore di 160 aa convertito per tagli proteolitici selettivi tessuto-specifici."},
{d:"Dove è espresso il gene del preproglucagone?",o:["Solo nelle cellule β del pancreas che secernono insulina","Esclusivamente negli epatociti, dove avviene la maturazione del precursore","Nelle cellule α pancreatiche, nelle cellule L intestinali e in alcuni neuroni","Solo nelle cellule parietali della mucosa gastrica e nel duodeno"],r:2,s:"Il gene del preproglucagone è espresso nelle cellule α del pancreas, nelle cellule L intestinali (enteroendocrine) e in alcuni neuroni del cervello."},
{d:"Quali ormoni possono derivare dal processamento del proglucagone?",o:["Solo glucagone e insulina","Gastrina, secretina e motilina","Glucagone, glicentina, oxintomodulina, GLP-1 e GLP-2","Solo GLP-1 e somatostatina"],r:2,s:"Il differente processamento del proglucagone genera glucagone, glicentina, oxintomodulina, GLP-1 e GLP-2."},
{d:"Da cosa dipende il diverso processamento del proglucagone nei vari tessuti?",o:["Dalla concentrazione intracellulare di ioni zinco nelle vescicole","Dall'emivita plasmatica del precursore nei diversi distretti tissutali","Dai livelli ematici di calcio e dal pH del compartimento secretorio","Dall'espressione dell'enzima pro-ormone convertasi: PC2 (→glucagone) o PC1/3 (→GLP)"],r:3,s:"Il processamento dipende dall'enzima pro-ormone convertasi: la PC2 (cellule α) porta a glucagone; la PC1/3 (cellule enteroendocrine e cervello) porta a GLP-1, GLP-2, glicentina e oxintomodulina."},
{d:"Quali sono le funzioni del GLP-1?",o:["Degrada l'insulina circolante riducendone l'azione sui tessuti bersaglio","Aumenta la glicemia stimolando direttamente la glicogenolisi epatica","Inibisce la secrezione di insulina e stimola quella di glucagone","Stimola l'insulina, inibisce il glucagone e aumenta la sazietà (svuotamento gastrico più lento)"],r:3,s:"Il GLP-1 stimola la secrezione di insulina e inibisce quella di glucagone (utile nel diabete insulino-resistente); rallenta lo svuotamento gastrico aumentando la sazietà e riducendo l'appetito."},
{d:"Quando viene secreto il glucagone e tramite quale via agisce?",o:["In bassa glicemia, via recettore accoppiato a proteine G → adenilato ciclasi → cAMP → PKA","In bassa glicemia, senza secondi messaggeri","In alta glicemia, via recettore tirosin-chinasico","In alta glicemia, via recettore intracellulare nucleare"],r:0,s:"Il glucagone è secreto in bassa glicemia e agisce su un recettore accoppiato a proteine G stimolatorie che attivano l'adenilato ciclasi: aumento di cAMP e attivazione della PKA. Bersagli: fegato e tessuto adiposo."},
{d:"Quali sono i principali effetti epatici del glucagone?",o:["+ glicogenolisi, + gluconeogenesi e + produzione di corpi chetonici","+ glicolisi, + glicogenosintesi e - chetogenesi","- gluconeogenesi e - glicogenolisi","Solo sintesi di glicogeno e di trigliceridi"],r:0,s:"Sul fegato il glucagone stimola glicogenolisi (attiva la glicogeno fosforilasi), gluconeogenesi (induce PEPCK e glucosio-6-fosfatasi) e produzione di corpi chetonici."},
{d:"Qual è l'effetto del glucagone sul tessuto adiposo?",o:["Stimola la lipolisi","Promuove la sintesi di trigliceridi","Inibisce la lipasi ormone-sensibile","Stimola la lipogenesi"],r:0,s:"Sul tessuto adiposo il glucagone stimola la lipolisi, con liberazione di acidi grassi e glicerolo."},
{d:"Quali sono le quattro azioni del glucagone sul metabolismo glucidico epatico?",o:["Attiva soltanto la piruvato chinasi favorendo l'utilizzo del fosfoenolpiruvato","Induce esclusivamente la trascrizione del gene della glucochinasi epatica","Stimola la glicolisi e la glicogenosintesi e inibisce la gluconeogenesi epatica","Inibisce glicogenosintesi/promuove glicogenolisi, stimola gluconeogenesi e induce enzimi via CREB"],r:3,s:"Via PKA il glucagone: inibisce la glicogenosintesi e promuove la glicogenolisi; riduce il F2,6BP stimolando la gluconeogenesi e inibendo la glicolisi; fosforila/inattiva la piruvato chinasi; induce enzimi gluconeogenici via CREB."},
{d:"Come il glucagone attiva la lipolisi nel tessuto adiposo via PKA?",o:["Inibisce la PKA bloccando l'esocitosi delle gocce lipidiche","Defosforila la perilipina e inattiva la lipasi","Attiva la lipoproteina-lipasi per immagazzinare i trigliceridi","Fosforila la perilipina e attiva la lipasi ormone-sensibile, liberando acidi grassi e glicerolo"],r:3,s:"La PKA attivata dal glucagone fosforila la perilipina (apre l'accesso alle gocce lipidiche) e fosforila/attiva la lipasi ormone-sensibile, mobilizzando i trigliceridi con liberazione di acidi grassi e glicerolo."},
{d:"Come il glucagone favorisce beta-ossidazione e chetogenesi a livello epatico?",o:["Stimolando la sintesi de novo di acidi grassi","Attivando l'acetil-CoA carbossilasi e aumentando il malonil-CoA","Bloccando la CPT-1 per impedire l'ingresso degli acili","Inducendo la CPT-1 e fosforilando/inibendo l'ACC, riducendo il malonil-CoA"],r:3,s:"Via PKA il glucagone attiva fattori trascrizionali (CREB, PPAR-α, FoxA2) inducendo la CPT-1; fosforila e inibisce l'ACC riducendo il malonil-CoA, promuovendo così la beta-ossidazione."},
{d:"Perché nel digiuno prolungato l'acetil-CoA è deviato verso i corpi chetonici?",o:["Perché aumenta il malonil-CoA che blocca la chetogenesi","Perché il ciclo di Krebs accelera consumando l'acetil-CoA","Perché l'ossalacetato è impiegato per la gluconeogenesi e l'acetil-CoA in eccesso forma corpi chetonici","Perché l'acetil-CoA viene completamente esaurito dal ciclo di Krebs"],r:2,s:"Nel digiuno l'ossalacetato è usato per la gluconeogenesi; non potendo condensare adeguatamente con l'acetil-CoA nel ciclo di Krebs, questo viene indirizzato verso la sintesi dei corpi chetonici."},
{d:"Quali sono i valori fisiologici di calcemia e fosfatemia?",o:["Calcemia 0,1 mg/100ml e fosfatemia 1 mg/100ml","Calcemia 10 mg/100ml e fosfatemia 5 mg/100ml","Calcemia 1 mg/100ml e fosfatemia 50 mg/100ml","Calcemia 100 mg/100ml e fosfatemia 0,5 mg/100ml"],r:1,s:"La calcemia fisiologica è circa 10 mg/100ml e la fosfatemia circa 5 mg/100ml."},
{d:"Quali processi dipendono da livelli adeguati di calcio?",o:["Solo la digestione e l'assorbimento dei carboidrati nel tenue","Esclusivamente la respirazione cellulare a livello della catena mitocondriale","Soltanto la sintesi e il deposito di glicogeno a livello epatico","Trasmissione nervosa, contrazione muscolare, coagulazione e mineralizzazione ossea"],r:3,s:"Livelli fisiologici di calcio garantiscono corretta trasmissione dell'impulso nervoso, contrazione muscolare, coagulazione del sangue e mineralizzazione di ossa e denti."},
{d:"Dove è depositata la maggior parte del calcio corporeo?",o:["Prevalentemente nel plasma sanguigno","Principalmente nei muscoli scheletrici","Soprattutto nel fegato e nella milza","Per circa il 99% nelle ossa come idrossiapatite"],r:3,s:"Il calcio è circa l'1,5% del peso corporeo; il 99% è depositato nelle ossa come idrossiapatite, in minima parte nel sangue e nei tessuti."},
{d:"Quali tre ormoni regolano l'omeostasi del calcio?",o:["Adrenalina, tiroxina e GH","Insulina, glucagone e cortisolo","Paratormone, calcitonina e calcitriolo","Gastrina, secretina e motilina"],r:2,s:"L'omeostasi del calcio è regolata da paratormone e calcitriolo (ipercalcemizzanti) e calcitonina (ipocalcemizzante)."},
{d:"Come avviene l'assorbimento intestinale del calcio?",o:["Solo grazie alla pompa sodio-potassio del versante basolaterale","Mediante endocitosi mediata da recettore con vescicole rivestite","Via canali TRPV6 e trasporto dalla calbindina (la cui sintesi dipende dalla vitamina D)","Per diffusione semplice attraverso la membrana, senza proteine specifiche"],r:2,s:"Nel tenue il calcio entra nell'enterocita via canali TRPV6 ed è veicolato al versante basolaterale dalla calbindina, la cui espressione dipende dalla vitamina D."},
{d:"Quali sono le caratteristiche della calcitonina?",o:["Polipeptide di 32 aa delle cellule C parafollicolari della tiroide, ipocalcemizzante","Ormone derivato dalla tirosina, iperglicemizzante","Ormone steroideo derivato dal colesterolo","Polipeptide di 84 aa delle paratiroidi, ipercalcemizzante"],r:0,s:"La calcitonina è un polipeptide di 32 aa prodotto dalle cellule C parafollicolari della tiroide come pro-ormone inattivo; è ipocalcemizzante."},
{d:"In risposta a quale stimolo viene secreta la calcitonina e con quale effetto?",o:["Ad alta fosfatemia, senza effetto sulla calcemia","Ad alta calcemia, agendo via proteina G/cAMP per ridurre il calcio ematico","A bassa calcemia, per aumentare il calcio ematico","A bassa glicemia, per mobilizzare il calcio osseo"],r:1,s:"La calcitonina è secreta in risposta all'aumento della calcemia e, via proteina G/cAMP, agisce su rene, osso e intestino per abbassare la calcemia (inibisce gli osteoclasti, il riassorbimento renale e l'assorbimento intestinale di Ca2+)."},
{d:"Quali sono le caratteristiche del paratormone (PTH)?",o:["Ormone steroideo derivato dal colesterolo con azione ipercalcemizzante","Polipeptide di 84 aa delle paratiroidi, attivato per proteolisi, ipercalcemizzante","Ormone derivato dalla tirosina con azione iperglicemizzante e lipolitica","Polipeptide di 32 aa prodotto dalle cellule C tiroidee, ipocalcemizzante"],r:1,s:"Il paratormone è un polipeptide di 84 aa prodotto dalle paratiroidi e attivato per proteolisi selettiva (25 aa nel RE, 6 aa nel Golgi); è ipercalcemizzante."},
{d:"In risposta a quale stimolo viene secreto il PTH e tramite quale recettore agisce?",o:["A bassa fosfatemia, senza secondi messaggeri","A bassa calcemia, via recettore di membrana accoppiato a proteine G (cAMP)","Ad alta calcemia, via recettore tirosin-chinasico","Ad alta glicemia, via recettore intracellulare"],r:1,s:"Il PTH è secreto in risposta alla diminuzione della calcemia e agisce su recettori di membrana accoppiati alle proteine G, con aumento di cAMP."},
{d:"Con quali azioni il paratormone aumenta la calcemia?",o:["Promuove riassorbimento osseo/renale di Ca2+ e attiva il calcitriolo (assorbimento intestinale)","Inibisce il riassorbimento osseo e quello renale degli ioni calcio","Inibisce la 1α-idrossilasi renale bloccando la sintesi di calcitriolo","Aumenta l'escrezione renale di calcio riducendo la calcemia plasmatica"],r:0,s:"Il PTH aumenta la calcemia tramite riassorbimento osseo, aumento del riassorbimento renale di Ca2+ (e ridotto riassorbimento di fosfato) e attivazione renale del calcitriolo, che aumenta l'assorbimento intestinale di Ca2+ e fosfato."},
{d:"Che tipo di ormone è il calcitriolo?",o:["Ormone steroideo ipercalcemizzante, forma attiva della vitamina D","Ormone peptidico ipocalcemizzante prodotto dalle paratiroidi","Eicosanoide a breve emivita derivato dall'acido arachidonico","Ormone derivato dalla tirosina con recettori di membrana"],r:0,s:"Il calcitriolo (1α,25-diidrossi vitamina D3) è un ormone steroideo ipercalcemizzante, forma attiva della vitamina D."},
{d:"Come si forma il colecalciferolo (vitamina D3) nella pelle?",o:["Dalla tirosina mediante idrossilazione enzimatica nei cheratinociti","Dal colesterolo per idrossilazione diretta a livello epatico","Esclusivamente dall'assunzione alimentare di colecalciferolo preformato","Dal 7-deidrocolesterolo che, con la luce UV, forma la pre-vitamina D3 poi isomerizzata"],r:3,s:"Nella pelle il 7-deidrocolesterolo (provitamina D3), per azione della luce UV, forma la pre-vitamina D3, che per isomerizzazione diventa vitamina D3 (colecalciferolo). La D3/D2 può anche provenire dalla dieta."},
{d:"Come viene trasportato il colecalciferolo nel sangue?",o:["Legato alla vitamina D binding protein, poi captato dal fegato","Legato all'emoglobina eritrocitaria","Incorporato nei chilomicroni linfatici","In forma libera, essendo idrofilico"],r:0,s:"Il colecalciferolo è trasportato nel sangue dalla vitamina D binding protein e captato dal fegato."},
{d:"Quali sono le due idrossilazioni che attivano la vitamina D3 e dove avvengono?",o:["Una nell'intestino e una nell'osso","Entrambe nel fegato, in C25 e in C1","C25 nel fegato (calcidiolo) e C1 nel rene (calcitriolo)","Entrambe nel rene, in C24 e C25"],r:2,s:"La vitamina D3 è idrossilata in C25 nel fegato (→ calcidiolo) e in C1 nel rene dalla 1α-idrossilasi mitocondriale (→ calcitriolo, forma attiva)."},
{d:"Quale ormone stimola la 1α-idrossilasi renale che attiva il calcitriolo?",o:["Il glucagone","Il paratormone","La calcitonina","L'insulina"],r:1,s:"Il paratormone stimola la 1α-idrossilasi renale che converte il calcidiolo in calcitriolo (forma attiva)."},
{d:"Come si regolano reciprocamente paratormone e calcitriolo?",o:["Entrambi si stimolano reciprocamente (doppio feedback positivo)","Feedback negativo del PTH sul calcitriolo e positivo del calcitriolo sul PTH","Feedback positivo del PTH sul calcitriolo e negativo del calcitriolo sul PTH","Non esiste alcuna regolazione reciproca"],r:2,s:"Il PTH esercita un feedback positivo sulla sintesi di calcitriolo, mentre il calcitriolo esercita un feedback negativo sulla sintesi del PTH."},
{d:"Con quali azioni il calcitriolo aumenta la calcemia?",o:["Stimola soltanto la deposizione di calcio nella matrice ossea","Induce la proteina legante il Ca2+ (intestino), aumenta gli osteoclasti (osso) e il riassorbimento renale","Promuove unicamente l'escrezione urinaria di calcio e fosfato","Inibisce gli osteoclasti e riduce il riassorbimento renale di calcio"],r:1,s:"Il calcitriolo agisce su intestino (sintesi della proteina legante il Ca2+ → assorbimento di Ca2+ e Pi), osso (aumento attività osteoclasti → mobilizzazione) e rene (riassorbimento), tramite recettore citosolico e modulazione genica."},
{d:"A quali patologie porta il deficit di vitamina D?",o:["Rachitismo o osteomalacia, con ossa poco mineralizzate e fragili","Insulino-resistenza periferica con iperinsulinemia compensatoria","Diabete mellito con glicosuria e poliuria persistente","Ipertensione arteriosa con sovraccarico cardiaco cronico"],r:0,s:"Il deficit di vitamina D causa rachitismo (bambini) o osteomalacia (adulti), con ridotta calcificazione ossea e formazione di strutture fragili."},
{d:"Qual è la vita media del calcitriolo e come viene eliminato?",o:["Pochi secondi, viene inattivato al primo passaggio polmonare","24 ore; idrossilato in C24 nel rene, poi eliminato con la bile","Circa 7 minuti, viene escreto rapidamente con le urine","Circa 48 ore, viene degradato lentamente nel plasma circolante"],r:1,s:"Il calcitriolo ha vita media di 24 ore; viene inattivato per idrossilazione in C24 nel rene, trasportato al fegato ed eliminato con la bile."},
{d:"Quali caratteristiche generali hanno gli ormoni gastrointestinali?",o:["Sono ormoni steroidei a lunga emivita prodotti dal fegato","Sono eicosanoidi sintetizzati dall'epitelio gastrico in risposta al pH","Sono derivati della tirosina prodotti dalla porzione endocrina del pancreas","Sono piccoli peptidi (≤40 aa) di cellule enteroendocrine/neuroni, secreti coi nutrienti"],r:3,s:"Gli ormoni gastrointestinali sono piccoli peptidi (≤40 aa) prodotti da cellule endocrine dell'epitelio gastrointestinale o da neuroni del sistema nervoso enterico, secreti in risposta ai nutrienti e a fattori come pH, calcio e distensione."},
{d:"Quali ormoni gastrointestinali regolano primariamente la funzione digestiva?",o:["Gastrina, secretina, colecistochinina e motilina","Solo la grelina e il GLP-1 di origine intestinale e cerebrale","Calcitonina e paratormone con azione sulla calcemia","Insulina e glucagone prodotti dalle isole di Langerhans"],r:0,s:"Gastrina, secretina, colecistochinina e motilina regolano primariamente la digestione; altri (grelina, GLP-1) agiscono anche sul cervello controllando fame e sazietà."},
{d:"Qual è la funzione della gastrina?",o:["Stimola le cellule parietali a secernere HCl e favorisce l'attivazione del pepsinogeno","Induce il pancreas a secernere enzimi digestivi","Riduce la motilità e la secrezione gastrica","Neutralizza l'acidità intestinale stimolando il bicarbonato"],r:0,s:"La gastrina, secreta dalla mucosa gastrica in risposta a stimoli meccanici e ai peptidi della dieta, stimola le cellule parietali a secernere succo gastrico (HCl) e favorisce l'attivazione del pepsinogeno in pepsina."},
{d:"Qual è la funzione della secretina (pancreozimina)?",o:["Induce la contrazione della colecisti","Aumenta direttamente il senso di fame","Stimola le cellule parietali a produrre HCl","Stimola il pancreas a secernere bicarbonato per neutralizzare l'acidità"],r:3,s:"La secretina, rilasciata in risposta all'HCl che giunge nell'intestino, stimola il pancreas a secernere bicarbonato (HCO3-) per neutralizzare l'acidità del chimo."},
{d:"Qual è la funzione della colecistochinina?",o:["Stimola il pancreas a secernere enzimi digestivi (in risposta ad acidi grassi e peptoni)","Stimola le cellule parietali a produrre HCl","Stimola la secrezione pancreatica di bicarbonato","Inibisce lo svuotamento gastrico riducendo la sazietà"],r:0,s:"La colecistochinina, rilasciata in risposta ad acidi grassi e peptoni nell'intestino, stimola il pancreas a secernere enzimi digestivi e induce la contrazione della colecisti."},
{d:"Oltre ai nutrienti, quali fattori stimolano la secrezione degli ormoni gastrointestinali?",o:["Esposizione alla luce e ritmo circadiano","Temperatura corporea e pressione arteriosa","pH, concentrazione di calcio e distensione delle pareti","Solo la concentrazione di glucosio ematico"],r:2,s:"Gli ormoni gastrointestinali sono secreti in risposta a pH, concentrazione di calcio e distensione delle pareti del tratto digestivo, oltre che ai nutrienti."},
{d:"In quali condizioni di glicemia avviene il rilascio di insulina dalle cellule β?",o:["In condizioni di alta glicemia, proporzionalmente al glucosio ematico","Solo durante il digiuno prolungato","In condizioni di bassa glicemia, come il glucagone","Indipendentemente dalla glicemia, a ritmo costante"],r:0,s:"Il rilascio di insulina avviene in condizioni di alta glicemia; la secrezione inizia circa 30-45 min dopo un pasto ed è proporzionale alla quantità di glucosio ematico."},
{d:"Perché il glicerolo liberato dalla lipolisi è definito un frammento glucogenico?",o:["Perché viene escreto immodificato con le urine","Perché si accumula nelle gocce lipidiche dell'adipocita","Perché può essere utilizzato come substrato per la gluconeogenesi","Perché viene convertito direttamente in acidi grassi"],r:2,s:"La lipolisi libera acidi grassi e glicerolo; quest'ultimo è un frammento glucogenico perché può entrare nella gluconeogenesi (via gliceraldeide-3-fosfato) contribuendo alla produzione di glucosio."},
]},
{p:"04_Ormoni_II_parte.pdf",m:2,q:[
{d:"La somatotropina (GH):",o:["è una proteina di 191 aa che agisce tramite recettore Tyr-chinasico associato al sistema JAK/STAT","è una glicoproteina di 191 aa che agisce tramite recettore accoppiato a proteine G stimolatorie","stimola la sintesi proteica e l'uptake di amminoacidi, ma non influenza la divisione cellulare","è secreta dall'ipofisi posteriore e agisce direttamente su fegato e ossa","stimola allungamento osseo e crescita muscolare mediante attivazione della PLC"],r:0,s:"Il GH è una proteina (non glicoproteina) di 191 aa che agisce tramite un recettore Tyr-chinasico associato al sistema JAK/STAT. È secreto dall'ipofisi anteriore (non posteriore) e stimola anche la divisione cellulare."},
{d:"Quale ormone ipofisario agisce nella ghiandola mammaria mediante recettore associato alle chinasi JAK/STAT inducendo la sintesi di lattoalbumina?",o:["Ossitocina","Somatotropina","Prolattina","FSH","LH"],r:2,s:"La prolattina (PRL) è una proteina di 199 aa che agisce nella ghiandola mammaria tramite recettore JAK/STAT. Induce la sintesi di lattoalbumina e di enzimi della via dei pentoso fosfati (G6PD e 6PGDH)."},
{d:"Nella sintesi del lattosio:",o:["la β-lattoalbumina si lega alla galattosiltransferasi: l'UDP-Gal va sul glucosio","l'α-lattoalbumina si lega alla galattosiltransferasi: l'UDP-Gal va sul glucosio","l'α-lattoalbumina si lega alla galattosiltransferasi: l'UDP-Gal va sul galattosio","l'enzima del lattosio è una transferasi che riconosce direttamente il glucosio","l'α-lattoalbumina si lega alla glucosidasi: l'UDP-Gal va sul glucosio"],r:1,s:"L'alfa-lattoalbumina (non beta) si lega alla galattosiltransferasi (che normalmente è aspecifica) e la rende specifica per il glucosio come accettore, generando lattosio."},
{d:"TSH, LH e FSH sono glicoproteine che:",o:["la subunità α media il legame al recettore; la β identica per tutti attiva l'adenilato ciclasi","subunità β comune e α diversa; la α specifica media il legame al recettore","agiscono tutte tramite IP3 e diacilglicerolo","subunità α comune e β diversa; la β specifica media il legame al recettore","subunità α comune e β diversa; la α specifica media il legame al recettore"],r:3,s:"TSH, LH e FSH condividono la subunità α (identica per tutti, media l'attivazione dell'adenilato ciclasi) mentre la subunità β è specifica per ciascun ormone e media l'interazione con il proprio recettore."},
{d:"Quale prodotto deriva dalla proteolisi selettiva della pro-opiomelanocortina (POMC) nella regione C-terminale?",o:["γ-melanotropina (γ-MSH)","ormone adrenocorticotropo (ACTH)","α-melanotropina (α-MSH)","β-lipotropina (β-LPH)","peptide corticotropo-simile (CLIP)"],r:3,s:"La POMC contiene nella regione C-terminale la sequenza della β-lipotropina (β-LPH, residui 42-134), in posizione intermedia l'ACTH, e nella porzione N-terminale la sequenza di MSH."},
{d:"La vasopressina:",o:["peptide di 9 aa (ponte Cys1-Cys6) che stimola il riassorbimento di acqua nei tubuli renali via cAMP","peptide di 9 aa (ponte Cys1-Cys6) che agisce tramite il sistema IP3/diacilglicerolo","peptide di 9 aa (ponte Cys1-Cys6); un suo deficit causa il diabete mellito di tipo 2","peptide di 11 aa (ponte Cys1-Cys6) che stimola il riassorbimento di acqua nei tubuli renali via cAMP","secreta dall'ipofisi anteriore, stimola il riassorbimento di acqua nei tubuli renali via cAMP"],r:0,s:"La vasopressina è un nonapeptide (9 aa) con ponte SS Cys1-Cys6 che agisce tramite cAMP stimolando il riassorbimento di acqua a livello renale. Il suo deficit causa il diabete insipido (non mellito). Il sistema IP3/DAG è usato dall'ossitocina."},
{d:"La tireoglobulina:",o:["lipoproteina di ~5000 aa con 115 tirosine, iodinata nella colloide dalla TPO","glicoproteina di ~5000 aa con 115 tirosine, iodinata nel reticolo endoplasmatico dalla TPO","glicoproteina di ~500 aa con 115 tirosine, iodinata nella colloide dalla TPO","glicoproteina di ~5000 aa con 115 fenilalanine, iodinata nella colloide dalla TPO","glicoproteina di ~5000 aa con 115 tirosine, iodinata nella colloide dalla TPO"],r:4,s:"La tireoglobulina è una glicoproteina di 5000 aa con 115 residui di tirosina. Nella colloide le tirosine vengono iodinare dalla tireoperossidasi (TPO) per dare MIT e DIT."},
{d:"Quale meccanismo utilizza la tireoperossidasi (TPO) per iodinare le tirosine della tireoglobulina?",o:["ossida lo ioduro (I⁻) a iodio (I⁰) usando NADPH, organificandolo nell'anello fenolico","ossida lo ioduro (I⁻) a iodio (I⁰) usando H₂O₂, organificandolo nell'anello fenolico","riduce lo ioduro (I⁻) a iodio (I⁰) usando H₂O₂, organificandolo nell'anello fenolico","ossida il iodio (I⁰) a ioduro (I⁻) usando H₂O₂, organificandolo nell'anello fenolico","ossida lo ioduro (I⁻) a iodio (I⁰) usando H₂O₂, organificandolo nell'anello imidazolico"],r:1,s:"La TPO ossida I⁻ a I⁰ usando H₂O₂ (che viene ridotta ad H₂O) per organificare lo iodio nell'anello fenolico (non imidazolico) della tirosina. I farmaci antitiroidei (tiouracile, propil-tiouracile, metimazolo) inibiscono questo processo."},
{d:"Riguardo alla captazione degli ioduri da parte della tiroide:",o:["trasporto contro gradiente, simporto I⁻/K⁺ accoppiato alla pompa Na/K, concentrazione tissutale 20×","trasporto contro gradiente, antiporto I⁻/Na⁺ accoppiato alla pompa Na/K, concentrazione tissutale 20×","trasporto contro gradiente, simporto I⁻/Na⁺ accoppiato alla pompa Na/K, concentrazione tissutale 20×","trasporto a favore di gradiente, simporto I⁻/Na⁺ accoppiato alla pompa Na/K, concentrazione tissutale 20×","trasporto contro gradiente, simporto I⁻/Na⁺ accoppiato alla pompa Na/K, concentrazione tissutale 10×"],r:2,s:"Il trasporto di I⁻ è attivo (contro gradiente), mediato da un simporto I⁻/Na⁺ accoppiato alla Na⁺/K⁺-ATPasi. Genera un rapporto tiroide:sangue di 20:1 (non 10:1)."},
{d:"Gli ormoni tiroidei circolano nel plasma legati principalmente a:",o:["Trans-tiretina (TTR) dal fegato, trasporta ~75% della T₄ e ~80% della T₃","TBG (Thyroxine Binding Globulin) dal rene, trasporta ~75% della T₄ e ~80% della T₃","TBG dal fegato, trasporta ~80% della T₄ e ~75% della T₃","TBG dal fegato, trasporta ~75% della T₄ e ~80% della T₃","Albumina con sito ad alta affinità per T₄ e T₃, trasporta ~75% della T₄"],r:3,s:"La TBG è una glicoproteina sintetizzata dal fegato (non dal rene) con alta affinità per T₄>T₃; trasporta circa il 75% della T₄ e l'80% della T₃. La TTR trasporta il 10% della T₄ e l'albumina circa il 12%."},
{d:"Quale affermazione descrive correttamente le deiodinasi degli ormoni tiroidei?",o:["DI nel muscolo e SNC; DII nel fegato e rene; DIII nel fegato, placenta e SNC","DI nel fegato e rene; DII nel muscolo, cuore e SNC; DIII nel fegato, placenta e SNC","DI nel fegato e rene; DII nel muscolo, cuore e SNC; DIII nella tiroide e rene","DI nel fegato e rene; DII nel muscolo, cuore e SNC; DIII genera T3 attiva dal T4","DI nel fegato e rene; DII nel muscolo, cuore e SNC; entrambe generano T3 inversa inattiva"],r:1,s:"La deiodinasi I è nel fegato e rene, la II nel muscolo scheletrico, cardiaco e SNC (entrambe generano T3 attiva da T4). La deiodinasi III è espressa nel fegato, placenta e SNC e genera la T3 inversa inattiva."},
{d:"La sintesi delle catecolammine:",o:["parte dalla tirosina; tappa limitante la tirosina idrossilasi (→DOPA), usa NADPH e BH₄","parte dalla fenilalanina; tappa limitante la tirosina idrossilasi (→DOPA), usa NADPH e BH₄","parte dalla tirosina; tappa limitante la DOPA decarbossilasi (→dopamina), usa PLP","parte dalla tirosina; tappa limitante la tirosina idrossilasi (→DOPA), usa NADH e BH₄","parte dalla tirosina; tappa limitante la dopamina β-idrossilasi, usa ascorbato e O₂"],r:0,s:"La tappa limitante è la tirosina idrossilasi (non la DOPA decarbossilasi né la dopamina β-idrossilasi) che usa NADPH e H₄BIOPT per convertire la tirosina in DOPA. La DOPA decarbossilasi usa PLP."},
{d:"I recettori α₁ adrenergici:",o:["accoppiati a proteina Gs: stimolano l'adenilato ciclasi aumentando l'AMPc","accoppiati a proteina Gi: inibiscono l'adenilato ciclasi riducendo l'AMPc","accoppiati a proteine G stimolatorie: ↑cAMP promuovendo glicogenolisi e lipolisi","attivano la PLC (PIP₂→DAG+IP₃) determinando il rilascio della muscolatura liscia","attivano la PLC (PIP₂→DAG+IP₃) determinando la contrazione della muscolatura liscia"],r:4,s:"I recettori α₁ sono accoppiati a proteine Gq che attivano la PLC, generando DAG e IP₃ con conseguente contrazione della muscolatura liscia. I recettori α₂ sono accoppiati a Gi (inibizione AC) e i β-adrenergici a Gs (aumento cAMP)."},
{d:"L'adrenalina, a differenza del glucagone:",o:["stimola la gluconeogenesi muscolare, col glucosio trasportato al fegato","stimola la fosforilasi epatica con produzione e accumulo di acido lattico","stimola anche la fosforilasi muscolare con produzione di acido lattico","nel pancreas stimola la secrezione di insulina aumentando il glucosio disponibile","stimola la glicogenolisi epatica col glucosio esportato direttamente in circolo"],r:2,s:"L'adrenalina, a differenza del glucagone, stimola anche la fosforilasi muscolare con produzione di lattato (il muscolo manca di glucosio-6-fosfatasi e non può esportare glucosio). Il lattato viene poi trasportato al fegato per la gluconeogenesi (ciclo di Cori)."},
{d:"Nel catabolismo dell'adrenalina a livello epatico:",o:["metilata da COMT (SAM) a met-adrenalina, poi deaminata da MAO; l'aldeide è ossidata ad acido omovanillico (NAD)","prima deaminata da MAO, poi metilata da COMT (SAM); l'aldeide è ossidata ad acido (NADP)","metilata da COMT con SAH a met-adrenalina, poi deaminata da MAO; l'aldeide ossidata ad acido (NAD)","metilata da COMT (SAM) a met-adrenalina, poi deaminata da MAO; l'aldeide ossidata ad acido (NADP)","metilata da COMT (SAM); poi coniugata ed escreta, o deaminata da MAO e ossidata ad acido (NAD)"],r:4,s:"Nel catabolismo epatico dell'adrenalina, COMT usa SAM (non SAH né NADP) per metilare l'adrenalina in met-adrenalina. Questa può essere coniugata con glucuronato o solfato ed escreta con le urine, oppure deaminata dalla MAO flavinica e poi ossidata da una deidrogenasi NAD-dipendente (non NADP) ad acido 3-metossi-4-idrossimandelico."},
{d:"La sintesi del pregnenolone:",o:["matrice mitocondriale, colesterolo via StAR, fosforilazione PKC-dipendente da ACTH/LH","nel citosol, colesterolo via StAR, fosforilazione cAMP-dipendente da ACTH/LH","matrice mitocondriale, colesterolo via StAR, fosforilazione cAMP-dipendente da CRH/LH","matrice mitocondriale, colesterolo via StAR, fosforilazione cAMP-dipendente da ACTH/LH","matrice mitocondriale, colesterolo via StAR; il pregnenolone resta nel mitocondrio e diventa progesterone"],r:3,s:"La sintesi del pregnenolone avviene nella matrice mitocondriale. La proteina STAR è attivata da fosforilazione cAMP-dipendente stimolata da ACTH (corteccia surrenale) o LH (gonadi). Il pregnenolone poi passa nel citosol dove viene convertito in progesterone."},
{d:"Il sistema renina-angiotensina-aldosterone (SRAA):",o:["in ipovolemia la renina forma ANG I; l'ACE polmonare/renale la converte in ANG II, che stimola l'aldosterone","in ipervolemia la renina forma ANG I; l'ACE polmonare/renale la converte in ANG II, che stimola l'aldosterone","in ipovolemia la renina forma ANG II direttamente; l'ACE la converte nella forma attiva","in ipovolemia la renina forma ANG I; l'ACE epatica la converte in ANG II, che stimola l'aldosterone","in ipovolemia la renina forma ANG I→ANG II, che stimola il riassorbimento di Na⁺ senza aldosterone"],r:0,s:"In ipovolemia (non ipervolemia) la renina genera ANG I; l'ACE nelle cellule endoteliali polmonari e renali (non epatiche) converte ANG I in ANG II, la quale stimola l'aldosterone dalla corteccia surrenale (oltre ad agire direttamente sui vasi e rene)."},
{d:"Il cortisolo:",o:["3-10% libero, 90% legato alla transcortina (CBG); si lega a recettori di membrana attivando il cAMP","3-10% libero, 90% legato alla transcortina (CBG); si lega a recettori intracellulari che migrano al nucleo","10-30% libero, 70% legato alla transcortina (CBG); si lega a recettori intracellulari che migrano al nucleo","3-10% libero, 90% legato alla CBG; per natura idrofila usa recettori di membrana Tyr-chinasici","stimola la gluconeogenesi epatica (PEPCK, G6Pasi...) ed è legato per il 90% alla TBG"],r:1,s:"Il cortisolo è lipofilico, diffonde passivamente e si lega a recettori intracellulari (non di membrana). La forma libera è il 3-10%, il 90% è legato alla transcortina/CBG (non TBG, che lega gli ormoni tiroidei)."},
{d:"La sintesi degli estrogeni a partire dagli androgeni:",o:["nelle ovaie l'aromatasi forma l'anello A eliminando il metile su C10, da 21 a 19 C; estradiolo più attivo","nelle ovaie l'aromatasi forma l'anello A eliminando il metile su C19, da 19 a 18 C; estradiolo più attivo","nelle ovaie l'aromatasi forma l'anello A eliminando il metile su C10, da 19 a 18 C; estradiolo più attivo","nei testicoli l'aromatasi forma l'anello A eliminando il metile su C10, da 19 a 18 C; estradiolo più attivo","nelle ovaie la 5α-reduttasi forma l'anello A eliminando il metile su C10; estradiolo più attivo"],r:2,s:"L'aromatasi (non la 5α-reduttasi) converte gli androgeni (C19) in estrogeni (C18) eliminando il gruppo metilico legato al C10 (non C19). La sintesi avviene principalmente nelle ovaie."},
{d:"Riguardo agli eicosanoidi:",o:["20 C, dall'acido linoleico (18:2 ω-6), in posizione 2 dei fosfolipidi, liberato dalla PLA₂","20 C, dall'AA (20:4 ω-3), in posizione 2 dei fosfolipidi, liberato dalla PLA₂","18 C, dall'AA (20:4 ω-6), in posizione 2 dei fosfolipidi, liberato dalla PLA₂","20 C, dall'AA (20:4 ω-6), in posizione 1 dei fosfolipidi, liberato dalla PLA₂","20 C, dall'AA (20:4 ω-6), in posizione 2 dei fosfolipidi, liberato dalla PLA₂"],r:4,s:"Gli eicosanoidi hanno 20 atomi di C e derivano dall'AA (20:4 ω-6, non ω-3). L'AA è esterificato prevalentemente in posizione 2 dei fosfolipidi (non posizione 1) e viene liberato dalla PLA₂."},
{d:"La ciclossigenasi-1 (COX-1) rispetto alla ciclossigenasi-2 (COX-2):",o:["enzima costitutivo nella maggior parte dei tessuti; entrambe le isoforme inibite irreversibilmente dall'aspirina","enzima inducibile nella maggior parte dei tessuti; entrambe le isoforme inibite irreversibilmente dall'aspirina","enzima costitutivo; la COX-1 è inibita irreversibilmente dall'aspirina, la COX-2 no","enzima costitutivo; entrambe le isoforme sono inibite reversibilmente dall'aspirina","enzima costitutivo delle piastrine che produce trombossani; entrambe inibite irreversibilmente dall'aspirina"],r:0,s:"COX-1 è costitutiva (COX-2 è inducibile). COX-1 media l'infiammazione in breve tempo ma con effetto limitato, COX-2 richiede più tempo ma produce maggiori quantità di prostanoidi. Entrambe vengono inibite irreversibilmente dall'aspirina (FANS non selettivo)."},
{d:"La prolattina (PRL):",o:["proteina di 199 aa, ipofisi anteriore, stimolo PRF, recettore Tyr-chinasico","proteina di 191 aa, ipofisi anteriore, stimolo PRF, recettore JAK/STAT","proteina di 199 aa, ipofisi posteriore, stimolo PRF, recettore JAK/STAT","proteina di 199 aa, ipofisi anteriore, stimolo PRF, recettore JAK/STAT","glicoproteina di 199 aa, ipofisi anteriore, stimolo PRF, recettore JAK/STAT"],r:3,s:"La PRL è una proteina (non glicoproteina) di 199 aa (non 191, che è il GH) secreta dall'ipofisi anteriore (non posteriore) sotto stimolo del PRF ipotalamico; agisce tramite recettore JAK/STAT (non Tyr-chinasico diretto)."},
{d:"L'ipofisi posteriore (neuroipofisi):",o:["produce corticotropina e tireotropina; peptidi di 9 aa con ponte Cys1-Cys6","produce vasopressina e ossitocina; peptidi di 9 aa, ponte Cys1-Cys6, amidazione C-terminale","produce vasopressina e ossitocina; peptidi di 11 aa, ponte Cys1-Cys6, amidazione C-terminale","produce POMC, processata in vari ormoni come ACTH, MSH e lipotropine","produce vasopressina e ossitocina; peptidi di 9 aa, ponte Cys3-Cys6, amidazione N-terminale"],r:1,s:"La neuroipofisi produce vasopressina e ossitocina, entrambi nonapeptidi (9 aa) con ponte SS Cys1-Cys6 e amidazione dell'estremità C-terminale (non N-terminale). La POMC è prodotta dall'ipofisi intermedia (e anteriore)."},
{d:"Quale delle seguenti affermazioni descrive correttamente l'ossitocina?",o:["stimola il riassorbimento di acqua nei tubuli renali via cAMP, con azione vasocostrittrice","stimola la contrazione della muscolatura liscia di utero e intestino e usa il sistema del cAMP","stimola la contrazione dell'utero e la produzione di latte, usa il sistema IP₃/diacilglicerolo","stimola la contrazione della muscolatura liscia uterina; un suo deficit causa il diabete insipido","stimola la contrazione uterina e usa il sistema IP₃; è secreta dall'ipofisi anteriore"],r:2,s:"L'ossitocina usa il sistema IP₃/DAG (non cAMP, che è usato dalla vasopressina). Il diabete insipido è causato da deficit di vasopressina, non ossitocina. L'ossitocina è secreta dall'ipofisi posteriore."},
{d:"Riguardo al diabete insipido:",o:["da eccesso di vasopressina, con riduzione del volume urinario sotto 500 ml/die","da deficit di ossitocina o ridotta sensibilità renale, con 10-20 litri di urine/die","da deficit di vasopressina o ridotta sensibilità renale, con 1-2 litri di urine/die","da deficit di vasopressina o ridotta sensibilità renale; causa oliguria e ritenzione idrica","da deficit di vasopressina o ridotta sensibilità renale, con 10-20 litri di urine/die"],r:4,s:"Il diabete insipido è causato da deficit di vasopressina (non ossitocina) o insensibilità renale ad essa. Si manifesta con poliuria (10-20 litri/die, non 1-2) e conseguente polidipsia compensatoria."},
{d:"Riguardo alla regolazione della sintesi degli ormoni tiroidei da parte del TSH:",o:["il TSH stimola pompa ioduri, sintesi e proteolisi della tireoglobulina; gli ormoni tiroidei inibiscono TSH e TRH","il TSH stimola pompa ioduri, sintesi e proteolisi della Tg; gli ormoni tiroidei stimolano TSH e TRH (feedback +)","il TSH inibisce pompa ioduri e sintesi della Tg ma stimola il riassorbimento; gli ormoni tiroidei inibiscono TSH e TRH","il TRH stimola direttamente pompa ioduri, sintesi e riassorbimento della Tg bypassando il TSH","il TSH stimola pompa ioduri, sintesi e proteolisi della Tg; gli ormoni tiroidei inibiscono il TSH ma non il TRH"],r:0,s:"Il TSH regola ogni passaggio della sintesi degli ormoni tiroidei. Il feedback negativo degli ormoni tiroidei inibisce sia TSH che TRH (non solo TSH). Il feedback è negativo, non positivo."},
{d:"Quale tra i seguenti è un effetto degli ormoni tiroidei sul metabolismo?",o:["in iperattività stimolano la lipogenesi con accumulo di grasso; a basse dosi stimolano la gluconeogenesi","basse dosi → glicogenolisi; alte dosi → gluconeogenesi; ↑UCP1/UCP2 e metabolismo basale","basse dosi → gluconeogenesi; alte dosi → glicogenolisi; ↓UCP1/UCP2 e metabolismo basale","basse dosi → gluconeogenesi; alte dosi → glicogenolisi; ↑UCP1/UCP2 e metabolismo basale","gluconeogenesi a tutte le dosi; ↑glicerolo-3P deidrogenasi e proteine disaccoppianti UCP1/UCP2"],r:3,s:"A basse concentrazioni gli ormoni tiroidei stimolano la gluconeogenesi; a concentrazioni più elevate favoriscono la glicogenolisi. In caso di ipertiroidismo stimolano la lipolisi (non lipogenesi). Promuovono UCP1/UCP2 aumentando il metabolismo basale."},
{d:"L'ipertiroidismo è causato da:",o:["insufficiente sintesi di tireoglobulina, con stanchezza, freddo e aumento di peso","anticorpo che lega i recettori del TSH mimandone gli effetti: gozzo, dimagrimento, instabilità nervosa","anticorpo che blocca i recettori del TSH impedendone gli effetti: gozzo, dimagrimento, instabilità nervosa","deficit della pompa degli ioduri, con ridotta produzione di T3/T4 e aumento del TSH","eccesso di TRH che stimola troppo il TSH, con iperproduzione di T3/T4 e dimagrimento"],r:1,s:"L'ipertiroidismo è causato da un anticorpo che mima il TSH (non che lo blocca) legandosi ai suoi recettori. L'ipotiroidismo è invece causato da insufficiente sintesi di tireoglobulina, ridotta captazione di ioduri, ecc."},
{d:"La proteina STAR nella steroidogenesi:",o:["trasporta il colesterolo nei mitocondri; attivata da fosforilazione PKA-dipendente da CRH/LH","trasporta il colesterolo nei lisosomi; attivata da fosforilazione cAMP-dipendente da ACTH/LH","trasporta il colesterolo nei mitocondri; attivata da fosforilazione cAMP-dipendente da ACTH/LH","trasporta il pregnenolone dal mitocondrio al citosol; attivata da fosforilazione cAMP da ACTH","trasporta il colesterolo nei mitocondri; attivata da cAMP da ACTH nella midollare o FSH nelle gonadi"],r:2,s:"La proteina STAR trasporta il colesterolo nei mitocondri (non lisosomi). È attivata da fosforilazione cAMP-dipendente stimolata da ACTH (corteccia surrenale) o LH (gonadi), non da CRH né FSH."},
{d:"Le reazioni di idrossilazione nella sintesi degli ormoni steroidei:",o:["monossigenasi mitocondriali (cit P450) e del reticolo; le mitocondriali usano NADPH: R-H+O₂+NADPH→R-OH+NADP+H₂O","monossigenasi mitocondriali (cit P450) e del reticolo; le mitocondriali usano NADH: R-H+O₂+NADH→R-OH+NAD+H₂O","diossigenasi mitocondriali (cit P450) e monossigenasi del reticolo; le mitocondriali usano NADPH","monossigenasi mitocondriali (cit P450); usano NADPH via catena adrenodossina reduttasi-adrenodossina","monossigenasi mitocondriali (cit P450) e del citosol; le mitocondriali usano NADPH"],r:0,s:"Le idrossilasi mitocondriali (cit P450) usano NADPH (non NADH) come donatore di elettroni tramite la catena adrenodossina reduttasi-adrenodossina. Esistono anche monossigenasi nel reticolo endoplasmatico (non citosol)."},
{d:"Nella sintesi della progesterone a partire dal pregnenolone:",o:["nel citosol la 3β-HSD riduce l'-OH in C3 e la Δ4,5-isomerasi sposta il doppio legame da C5 a C4","nel mitocondrio la 3β-HSD ossida l'-OH in C3 e la Δ4,5-isomerasi sposta il doppio legame da C5 a C4","nel citosol la 17α-idrossilasi ossida l'-OH in C17 e la Δ4,5-isomerasi sposta il legame da C5 a C4","nel citosol la 3β-HSD ossida l'-OH in C3 e la Δ4,5-isomerasi sposta il doppio legame da C4 a C5","nel citosol la 3β-HSD ossida l'-OH in C3 e la Δ4,5-isomerasi sposta il doppio legame da C5 a C4"],r:4,s:"La conversione è citosolica (non mitocondriale). La 3β-HSD ossida (non riduce) il gruppo -OH in C3 a chetone, e la delta 4,5-isomerasi sposta il doppio legame da C5 a C4 (non viceversa). La 17α-idrossilasi non è coinvolta in questa tappa."},
{d:"L'aldosterone:",o:["glucocorticoide della zona glomerulare, dal progesterone; stimola il riassorbimento di Na⁺/Cl⁻ e la volemia","mineralcorticoide della zona glomerulare, dal progesterone; stimola il riassorbimento di Na⁺/Cl⁻ e la volemia","mineralcorticoide della zona fascicolata, dal progesterone; stimola il riassorbimento di Na⁺/Cl⁻ e la volemia","mineralcorticoide della zona glomerulare, dal cortisolo; stimola il riassorbimento di Na⁺/Cl⁻","mineralcorticoide della zona glomerulare, dal progesterone; stimola l'escrezione di Na⁺/Cl⁻ riducendo la volemia"],r:1,s:"L'aldosterone è un mineralcorticoide (non glucocorticoide) della zona glomerulare (non fascicolata). Il suo precursore diretto è il progesterone (non il cortisolo). Stimola il riassorbimento (non escrezione) di Na⁺ e Cl⁻ aumentando la volemia."},
{d:"Il recettore AT1R dell'angiotensina II:",o:["accoppiato a proteine Gi; la α attiva la PLC (IP₃+DAG); l'IP₃ libera Ca²⁺ e il DAG attiva la PKC","accoppiato a proteine G; la α attiva l'adenilato ciclasi (cAMP); la PKA fosforila fattori per l'aldosterone","recettore Tyr-chinasico; genera IP₃+DAG; l'IP₃ libera Ca²⁺ e il DAG attiva la PKC per l'aldosterone","accoppiato a proteine G; la α attiva la PLC (IP₃+DAG); l'IP₃ libera Ca²⁺ e il DAG attiva la PKC per l'aldosterone","accoppiato a proteine G; la α attiva la PLC; il DAG libera Ca²⁺ e l'IP₃ attiva la PKC per l'aldosterone"],r:3,s:"AT1R è accoppiato a proteine Gq (non Gi né Tyr-chinasico) che attiva la PLC generando IP₃ e DAG. È l'IP₃ (non il DAG) a liberare Ca²⁺ dal reticolo, e il DAG attiva la PKC per la sintesi dell'aldosterone."},
{d:"Riguardo alla sintesi del cortisolo nella zona fascicolata:",o:["17β-idrossilasi → 17α-OH-pregnenolone; 3β-HSD+Δ4,5-isomerasi → 17α-OH-progesterone; idrossilazioni C21 e C11 → cortisolo","dal progesterone via 17α-idrossilasi → 17α-OH-progesterone; idrossilazioni C11 e C21 → cortisolo (ACTH/cAMP)","17α-idrossilasi → 17α-OH-pregnenolone; 3β-HSD+Δ4,5-isomerasi; idrossilazioni C11 e C21 → cortisolo (ACTH/cAMP)","21α-idrossilasi → 17α-OH-pregnenolone; 3β-HSD+Δ4,5-isomerasi → 17α-OH-progesterone; idrossilazioni C21 e C11 → cortisolo","17α-idrossilasi → 17α-OH-pregnenolone; 3β-HSD+Δ4,5-isomerasi → 17α-OH-progesterone; poi C21 e C11 → cortisolo (ACTH/cAMP)"],r:4,s:"La sequenza corretta è: pregnenolone → 17α-OH-pregnenolone (17α-idrossilasi, non 21α-idrossilasi) → 17α-OH-progesterone (3β-HSD + delta 4,5-isomerasi) → cortisolo (idrossilazioni in C21 poi C11). La regolazione è ACTH/cAMP-dipendente."},
{d:"Il cortisone:",o:["precursore inerte del cortisolo; attivato per riduzione del chetone in C11 dalla 11β-HSD2","precursore inerte del cortisolo; attivato per ossidazione dell'-OH in C11 dalla 11β-HSD1","precursore inerte del cortisolo; attivato per riduzione del chetone in C11 dalla 11β-HSD1","prodotto di inattivazione del cortisolo; la 11β-HSD2 lo forma per ossidazione in C17","precursore inerte del cortisolo; attivato per riduzione del chetone in C17 dalla 11β-HSD1"],r:2,s:"Il cortisone è il precursore inerte convertito in cortisolo per riduzione del chetone in C11 (non C17) dalla 11β-HSD1 (non HSD2; la HSD2 catalizza la reazione inversa nel rene). Il cortisolo è la forma attiva antinfiammatoria."},
{d:"Quale delle seguenti affermazioni descrive correttamente il testosterone?",o:["nelle gonadi (Leydig) per riduzione dell'androstenedione; agisce dopo conversione a DHT via 5α-reduttasi NADPH","nelle gonadi e nel surrene (cellule di Sertoli) per riduzione dell'androstenedione; agisce dopo conversione a DHT","nelle gonadi (Leydig) per riduzione dell'androstenedione; agisce direttamente senza conversione a DHT","nelle gonadi (Leydig) per ossidazione dell'androstenedione; agisce dopo conversione a DHT via 5α-reduttasi","nelle gonadi (Leydig) per riduzione dell'androstenedione; agisce dopo conversione a DHT via 5β-reduttasi"],r:0,s:"Il testosterone è sintetizzato solo nelle gonadi (l'androstenedione si forma anche nella corteccia surrenale). È prodotto dalle cellule di Leydig (non Sertoli) per riduzione (non ossidazione) dell'androstenedione. La conversione a DHT avviene per opera della 5α-reduttasi (non 5β)."},
{d:"Riguardo alla trasduzione del segnale degli ormoni tiroidei nelle cellule bersaglio:",o:["T3 si lega nel nucleo al TR, che dimerizza con il RAR; il complesso lega il TRE e attiva la trascrizione","T4 (forma attiva) si lega nel nucleo al TR, che dimerizza con l'RXR; il complesso lega il TRE","T3 si lega nel citoplasma al TR, che dimerizza con l'RXR e migra nel nucleo legando il TRE","T3 si lega nel nucleo al TR, che dimerizza con l'RXR; il complesso lega il TRE e attiva la trascrizione","T3 si lega nel nucleo al TR; il complesso attiva direttamente la RNA polimerasi senza dimerizzare"],r:3,s:"T3 (non T4) è la forma che agisce nel nucleo. Il TR lega T3, rilascia il co-repressore, dimerizza con RXR (recettore retinoide X, non RAR) e il complesso lega il TRE attivando la trascrizione. Il legame avviene nel nucleo (non citoplasma)."},
{d:"Nella sintesi degli androgeni a partire dal pregnenolone nel citosol:",o:["17α-idrossilasi → 17α-OH-pregnenolone; la desmolasi genera androstenedione diretto; nelle gonadi → testosterone","17α-idrossilasi → 17α-OH-progesterone; la desmolasi genera DHEA; deidrogenasi/isomerasi → androstenedione","17α-idrossilasi → 17α-OH-pregnenolone; desmolasi → DHEA; deidrogenasi/isomerasi → androstenedione; nelle gonadi → testosterone","21α-idrossilasi → 17α-OH-pregnenolone; desmolasi → DHEA; deidrogenasi/isomerasi → androstenedione; nelle gonadi → testosterone","17α-idrossilasi → 17α-OH-pregnenolone; desmolasi → DHEA → androstenedione; la 5α-reduttasi lo converte direttamente in DHT"],r:2,s:"La via corretta è: pregnenolone → 17α-OH-pregnenolone (17α-idrossilasi) → DHEA (desmolasi) → androstenedione (deidrogenasi + isomerasi). Solo nelle gonadi l'androstenedione reduttasi genera testosterone. La 5α-reduttasi converte il testosterone (non androstenedione) in DHT nei tessuti bersaglio."},
{d:"Le prostacicline rispetto ai trombossani:",o:["prostacicline vasodilatatorie/antiaggreganti/ipotensive da PGH₂; i leucotrieni vasocostrittori da lipossigenasi","prostacicline vasocostrittrici/aggreganti/ipertensive; trombossani vasodilatatori/antiaggreganti; entrambi da PGH₂","prostacicline vasodilatatorie/antiaggreganti; trombossani vasocostrittori/aggreganti; entrambi da lipossigenasi","prostacicline vasodilatatorie/antiaggreganti; trombossani vasocostrittori/aggreganti; le prime da COX-1, i secondi da COX-2","prostacicline vasodilatatorie/antiaggreganti/ipotensive; trombossani vasocostrittori/aggreganti/ipertensivi; entrambi da PGH₂"],r:4,s:"Prostacicline (vasodilatazione, antiaggregazione, ipotensione) e trombossani (vasocostrizione, ipertensione, aggregazione) derivano entrambi da PGH₂ tramite la ciclossigenasi (non dalla lipossigenasi, che produce i leucotrieni). Non è una distinzione COX-1/COX-2."},
{d:"I leucotrieni:",o:["prodotti dalla lipossigenasi dall'AA nelle piastrine; coinvolti in infiammazione e allergie","prodotti dalla ciclossigenasi dall'AA nei globuli bianchi; coinvolti in infiammazione e allergie","prodotti dalla lipossigenasi dall'AA nei globuli bianchi; coinvolti in infiammazione e allergie","prodotti dalla lipossigenasi dall'EPA nei globuli bianchi; coinvolti in infiammazione e allergie","prodotti dalla lipossigenasi dall'AA nei globuli bianchi; hanno azione vasodilatatoria e antiaggregante"],r:2,s:"I leucotrieni derivano dall'acido arachidonico (non EPA) per azione della lipossigenasi (non ciclossigenasi) nei globuli bianchi (non piastrine) e mediano infiammazione e allergie. L'azione vasodilatatoria e antiaggregante è delle prostacicline."},
{d:"Quale affermazione descrive correttamente l'aspirina come inibitore della ciclossigenasi?",o:["inibisce reversibilmente COX-1 e COX-2 acetilando una serina; i coxib (celecoxib) inibiscono selettivamente la COX-1","inibisce irreversibilmente COX-1 e COX-2 acetilando una serina; il Brufen blocca il canale d'accesso dell'AA","inibisce irreversibilmente COX-1 e COX-2 acetilando una tirosina; il Brufen blocca il canale d'accesso dell'AA","inibisce irreversibilmente COX-1 e COX-2 acetilando una serina; è selettiva per COX-2 e i coxib non lo sono","inibisce irreversibilmente la COX-2 ma non la COX-1 acetilando una serina; il Brufen blocca l'accesso dell'AA"],r:1,s:"L'aspirina inibisce irreversibilmente (non reversibilmente) sia COX-1 che COX-2 acetilando la serina (non tirosina) del sito attivo. È non selettiva. Il Brufen blocca il canale di accesso dell'AA. I coxib (celecoxib, rofecoxib) sono inibitori selettivi di COX-2 (non COX-1)."},
]},
];

let _n = 0;
export const defaultQuestions = RAW.flatMap(g =>
  g.q.map(x => ({
    id: `q_${String(++_n).padStart(3, '0')}`,
    modulo: g.m,
    pdf_origine: g.p,
    domanda: x.d,
    opzioni: x.o,
    rispostaCorretta: x.r,
    spiegazione: x.s
  }))
);
